window.AponarQuartet2Data={"q2":{"chapters.theme_bn":{"প্রসঙ্গ, পরোক্ষ কথা ও ভাষার সূক্ষ্ম পার্থক্য":"प्रसंग, अप्रत्यक्ष बात और भाषा का सूक्ष्म अंतर","যুক্তি, বিকল্প দৃষ্টিকোণ ও মতামত গঠন":"तर्क, वैकल्पिक दृष्टिकोण और राय गठन","অভিজ্ঞতা থেকে শেখা ও ভদ্রভাবে মতের পার্থক্য বলা":"अनुभव से सीखना और विनम्रता से राय का अंतर कहना","কাজের মূল্যবোধ, সাক্ষাৎকার নেওয়া ও তথ্য সাজানো":"काम के मूल्यबोध, साक्षात्कार लेना और जानकारी सजाना","ঘটনার মোড়, উপমা ও অনুভূতির পরিবর্তন পড়া":"घटना का मोड़, उपमा और भावना का परिवर्तन पढ़ना","তুলনা, পরিবর্তনের প্রবণতা ও সীমিত সিদ্ধান্ত":"तुलना, परिवर्तन की प्रवृत्ति और सीमित निर्णय"},"chapters.title_bn":{"অধ্যায় ৮ · পেশাদারিত্ব ও সাক্ষাৎকার":"अध्याय 8 · पेशेवरता और साक्षात्कार","অধ্যায় ১০ · তথ্য দিয়ে সমাজ বোঝা":"अध्याय 10 · जानकारी से समाज समझना","অধ্যায় ৯ · গল্প, অনুভূতি ও পর্যালোচনা":"अध्याय 9 · कहानी, भावना और समीक्षा","অধ্যায় ১২ · চিন্তার পরিবর্তন ও সমাজ":"अध्याय 12 · सोच का परिवर्तन और समाज","অধ্যায় ১১ · শব্দের আড়ালের অর্থ":"अध्याय 11 · शब्दों के पीछे का अर्थ","অধ্যায় ৭ · ভিন্ন সংস্কৃতি, নতুন উপলব্ধি":"अध्याय 7 · भिन्न संस्कृति, नई अनुभूति"},"form_guide.label":{"সম্ভাব্য রূপ":"संभाव्य रूप","い-বিশেষণ":"い-विशेषण","な-বিশেষণ":"な-विशेषण","ইচ্ছার রূপ":"इच्छा का रूप"},"form_guide.meaning_bn":{"বর্তমান বা ভবিষ্যতের সাধারণ নেতিবাচক রূপ।":"वर्तमान या भविष्य का सामान्य नकारात्मक रूप।","ます・です ছাড়া সাধারণ রূপ: বর্তমান, অতীত, ইতিবাচক ও নেতিবাচক। N ও な-বিশেষণের だ কখন বাদ/な/の হবে তা প্রতিটি নিয়মে দেওয়া আছে।":"ます・です के बिना सामान्य रूप: वर्तमान, भूत, सकारात्मक और नकारात्मक। N और な-विशेषण का だ कब हटेगा/な/の होगा, यह प्रत्येक नियम में दिया है।","বিশেষ্যকে বর্ণনা করলে な লাগে। সব গঠনে な থাকবে না; পাঠের সংযোগ দেখুন।":"संज्ञा का वर्णन करने पर な लगता है। सभी संरचनाओं में な नहीं रहेगा; पाठ का संयोजन देखें।","সাধারণ অতীত রূপ।":"सामान्य भूत रूप।","ます-রূপ থেকে শুধু ます বাদ দিন।":"ます-रूप से सिर्फ़ ます हटाएँ।","“করি/করব” ধরনের volitional form।":"\"करूँ/करूँगा\" प्रकार का volitional form।","ক্রিয়ার সংযোগের て-form; কোথাও で হয়।":"क्रिया के संयोजन का て-form; कहीं で होता है।","কোনো কাজ করতে পারা বোঝায়।":"कोई काम कर सकना समझाता है।","বিশেষ্য: ব্যক্তি, বস্তু বা বিষয়ের নাম।":"संज्ञा: व्यक्ति, वस्तु या विषय का नाम।","い-বিশেষণ, যেমন বড়, দামি। নেতিবাচক ও অতীতে রূপ বদলায়।":"い-विशेषण, जैसे बड़ा, महँगा। नकारात्मक और भूत में रूप बदलता है।","ক্রিয়ার dictionary form; এর মানে সব ক্রিয়া る দিয়ে শেষ হবে না।":"क्रिया का dictionary form; इसका मतलब सभी क्रियाएँ る से समाप्त नहीं होंगी।","শর্তের ば-form।":"शर्त का ば-form।"},"lessons.examples.bangla":{"সংস্কৃতি আলাদা বলেই আলোচনা করা জরুরি।":"संस्कृति अलग है कहकर ही चर्चा करना ज़रूरी।","তিনি শিক্ষক বলার চেয়ে বরং বন্ধুর মতো।":"वह शिक्षक कहने से बल्कि दोस्त जैसा है।","আগামীকাল হলে সাহায্য করা একেবারে অসম্ভব নয়।":"कल होने पर सहायता करना बिल्कुल असंभव नहीं।","বয়স বাড়ার সঙ্গে চিন্তার ধরনও বদলায়।":"उम्र बढ़ने के साथ सोच का ढंग भी बदलता है।","শিশুটি কাঁদল মনে হতেই সঙ্গে সঙ্গে হাসল।":"बच्चा रोया लगते ही साथ ही हँसा।","বিস্তৃত এলাকাজুড়ে জরিপ প্রয়োজন।":"विस्तृत क्षेत्र भर सर्वेक्षण आवश्यक।","খাবারটি যে খেতে পারি না তা নয়, তবে একটু ঝাল।":"खाना खा नहीं सकता ऐसा नहीं, लेकिन थोड़ा तीखा है।","গত বছরের তুলনায় ব্যবহারকারী বেড়েছে।":"पिछले वर्ष की तुलना में उपयोगकर्ता बढ़े हैं।","বসন্ত হলেও সকালে এখনো ঠান্ডা।":"वसंत होने पर भी सुबह अभी ठंड है।","যান বা না যান, জানাবেন।":"जाएँ या न जाएँ, बताएँगे।","এভাবে চললে দুর্ঘটনার আশঙ্কা আছে।":"इस तरह चलने पर दुर्घटना की आशंका है।","বাইরে বের হওয়া মাত্রই বৃষ্টি শুরু হলো।":"बाहर निकलते ही बारिश शुरू हुई।","বন্ধুর সঙ্গে দেখা হওয়ার সূত্রে আমার চিন্তা বদলেছে।":"दोस्त से मुलाकात होने के सूत्र से मेरी सोच बदली है।","না করলেও ভদ্রভাবে জানানো ভালো।":"न करने पर भी विनम्रता से बताना अच्छा।","টোকিওর তুলনায় এই শহরে ভাড়া কম।":"टोक्यो की तुलना में इस शहर में किराया कम है।","এইমাত্র বেরিয়েছে, তাই ইতিমধ্যে পৌঁছে যাওয়ার কথা নয়।":"अभी-अभी निकला है, इसलिए पहले ही पहुँच जाने की बात नहीं।","বিষয়বস্তু যাচাই করার পরে স্বাক্ষর করুন।":"विषयवस्तु जाँचने के बाद हस्ताक्षर करें।","জাপানিতে অভ্যস্ত হওয়ার সঙ্গে কথা বলা আনন্দদায়ক হয়েছে।":"जापानी में अभ्यस्त होने के साथ बात करना आनंददायक हुआ है।","কথা দিয়েছি বলে এখন আর না করা চলে না।":"वादा किया है कहकर अब और न करना नहीं चलता।","এই প্রস্তাব সম্পর্কে আমার প্রশ্ন আছে।":"इस प्रस्ताव के बारे में मेरा प्रश्न है।","মতবিনিময় অনুষ্ঠানকে উপলক্ষ করে স্থানীয় কাজে যুক্ত হয়েছি।":"राय-विनिमय कार्यक्रम को अवसर बनाकर स्थानीय काम में जुड़ा हूँ।","ট্রেন বন্ধ হওয়ায় ট্যাক্সি নেওয়া ছাড়া উপায় ছিল না।":"ट्रेन बंद होने से टैक्सी लेने के सिवा उपाय नहीं था।","তিনি হাল না ছেড়ে অনুশীলন চালিয়েছেন।":"उसने हार न मानकर अभ्यास जारी रखा है।","মনে হচ্ছিল যেন স্বপ্ন দেখছি।":"लग रहा था जैसे सपना देख रहा हूँ।","অতিথির চাহিদা অনুযায়ী কক্ষের ব্যবস্থা করব।":"अतिथि की माँग के अनुसार कक्ष की व्यवस्था करूँगा।","প্রিয় বন্ধু বলেই সৎভাবে জানাতে চাই।":"प्रिय दोस्त है कहकर ही ईमानदारी से बताना चाहता हूँ।","প্রতিদিন অনুশীলন করছে, নিশ্চয়ই দক্ষ হবে বলে মনে করি।":"हर दिन अभ्यास कर रहा है, निश्चित ही दक्ष होगा ऐसा मानता हूँ।","ব্যাখ্যা পড়েছি ঠিকই, কিন্তু ব্যবহারের পদ্ধতি এখনো বুঝিনি।":"व्याख्या पढ़ी है सही, लेकिन उपयोग की विधि अभी नहीं समझा।","দোকানটি সারা বছর খোলা থাকে।":"दुकान पूरे वर्ष खुली रहती है।","এত সহজ উপায়ে সব মনে রাখা যাবে, এমন নয় মোটেও।":"इतने आसान उपाय से सब याद रखा जा सकेगा, ऐसा बिल्कुल नहीं।","শুধু বিদেশি শিক্ষার্থী নয়, এলাকার মানুষও অংশ নিতে পারেন।":"सिर्फ़ विदेशी विद्यार्थी नहीं, क्षेत्र के लोग भी भाग ले सकते हैं।","আমার জানা মতে দোকানটি রবিবারও খোলা থাকে।":"मेरी जानकारी के अनुसार दुकान रविवार को भी खुली रहती है।","ব্যবস্থার পরিবর্তনের সঙ্গে প্রক্রিয়াও বদলেছে।":"व्यवस्था के परिवर्तन के साथ प्रक्रिया भी बदली है।","টাইফুনের কারণে ট্রেন বন্ধ হওয়ার আশঙ্কা আছে।":"तूफ़ान के कारण ट्रेन बंद होने की आशंका है।","তিনি পথঘাট ভালো জানেন, নিশ্চয়ই স্থানীয় বলে মনে হয়।":"वह रास्ते अच्छी तरह जानता है, निश्चित ही स्थानीय है ऐसा लगता है।","জ্বর আছে বলে বিশ্রাম না নিয়ে থাকা চলে না।":"बुख़ार है कहकर विश्राम न लेकर रहना नहीं चलता।","মতবিনিময় অনুষ্ঠানের মাধ্যমে নতুন বন্ধু হয়েছে।":"राय-विनिमय कार्यक्रम के माध्यम से नया दोस्त बना है।","সুস্থ থাকা পর্যন্ত কাজ চালিয়ে যেতে চাই।":"स्वस्थ रहने तक काम जारी रखना चाहता हूँ।","সফল হব কি না তা প্রস্তুতির ওপর নির্ভর করে।":"सफल होऊँगा या नहीं यह तैयारी पर निर्भर करता है।","আকাশ অন্ধকার হলো মনে হতেই প্রবল বৃষ্টি নামল।":"आकाश अंधेरा हुआ लगते ही प्रबल बारिश उतरी।","বড় ভাই সকালে স্বচ্ছন্দ, এর বিপরীতে ছোট ভাই রাতে স্বচ্ছন্দ।":"बड़ा भाई सुबह सहज, इसके विपरीत छोटा भाई रात में सहज।","ছোটবেলায় নদীতে প্রায়ই খেলতাম।":"बचपन में नदी में प्रायः खेलता था।","এটি বাস্তব অভিজ্ঞতার ভিত্তিতে লেখা প্রতিবেদন।":"यह वास्तविक अनुभव के आधार पर लिखी रिपोर्ट है।","বিদেশের জীবন আনন্দের, আবার পরিবারের জন্য মনও খারাপ হয়।":"विदेश का जीवन आनंद का है, फिर परिवार के लिए मन भी ख़राब होता है।","অংশ নিন বা না নিন, উত্তর দিন।":"भाग लें या न लें, उत्तर दें।","এই সমস্যা শুধু জাপানে নয়, অন্য দেশেও আছে।":"यह समस्या सिर्फ़ जापान में नहीं, अन्य देशों में भी है।","কক্ষটি শান্ত বলার চেয়ে বরং নির্জন লাগে।":"कक्ष शांत कहने से बल्कि निर्जन लगता है।","তিন দিনজুড়ে প্রশিক্ষণ অনুষ্ঠিত হয়েছে।":"तीन दिन भर प्रशिक्षण आयोजित हुआ है।","শহর একদিকে সুবিধাজনক, অন্যদিকে জীবনযাত্রার খরচ বেশি।":"शहर एक ओर सुविधाजनक, दूसरी ओर जीवनयापन का ख़र्च अधिक।","কারণ না জেনে বিচার করা উচিত নয়।":"कारण न जानकर विचार नहीं करना चाहिए।","জাপানি হলেও সবাই যে কানজিতে দক্ষ তা নয়।":"जापानी होने पर भी सभी kanji में दक्ष हैं ऐसा नहीं।","গ্রাহকসেবার ক্ষেত্রে অন্যের কথা শোনা জরুরি।":"ग्राहक सेवा के मामले में दूसरों की बात सुनना ज़रूरी है।","জাপানি বলতে পারলেও সম্মানসূচক ভাষায় আত্মবিশ্বাস নেই।":"जापानी बोल सकने पर भी सम्मानसूचक भाषा में आत्मविश्वास नहीं।","কণ্ঠস্বর শোনা মাত্রই স্বস্তি পেলাম।":"आवाज़ सुनते ही राहत मिली।","অভিজ্ঞতার সঙ্গে মানানসই কাজের দায়িত্ব দেব।":"अनुभव से उपयुक्त काम का दायित्व दूँगा।","আগে বন্ধুদের সঙ্গে প্রায়ই দীর্ঘ চিঠি লিখতাম।":"पहले दोस्तों के साथ प्रायः लंबी चिट्ठियाँ लिखता था।","সুবিধা বেড়েছে ঠিকই, তবু সমস্যা রয়ে গেছে।":"सुविधा बढ़ी है सही, फिर भी समस्या रह गई है।","জরিপের ফলকে ভিত্তি করে পরিকল্পনা করেছি।":"सर्वेक्षण के परिणाम को आधार बनाकर योजना बनाई है।","চালিয়ে যেতে পেরেছি ঠিক সহকর্মীরা পাশে ছিলেন বলেই।":"जारी रख सका ठीक सहकर्मी साथ थे कहकर ही।","তিনি এমনভাবে কথা বললেন যেন কিছুই জানেন না।":"उसने इस तरह बात कही जैसे कुछ नहीं जानता।","বন্ধুর জন্য চিন্তায় যোগাযোগ না করে থাকতে পারিনি।":"दोस्त के लिए चिंता में संपर्क न करके रह नहीं सका।","দামি জিনিস সবসময় ভালো হবে এমন নয়।":"महँगी चीज़ हमेशा अच्छी होगी ऐसा नहीं।","সহযোগিতা হলো একই লক্ষ্যে একসঙ্গে কাজ করা।":"सहयोग है एक ही लक्ष्य में एक साथ काम करना।","প্রবল বৃষ্টিতে পরিকল্পনা বদলানো ছাড়া উপায় নেই।":"प्रबल बारिश में योजना बदलने के सिवा उपाय नहीं।","সূচি ঠিক হওয়া মাত্র জানাব।":"सूची तय होते ही बताऊँगा।","বয়স নির্বিশেষে যে কেউ অংশ নিতে পারেন।":"उम्र निर्विशेष कोई भी भाग ले सकता है।","কেইগো বলতে অন্যের প্রতি সম্মান প্রকাশের ভাষা বোঝায়।":"けいご से दूसरों के प्रति सम्मान प्रकट करने की भाषा समझाई जाती है।","জনসংখ্যা বৃদ্ধির সঙ্গে আবাসনের প্রয়োজন বেড়েছে।":"जनसंख्या वृद्धि के साथ आवास की आवश्यकता बढ़ी है।","আমি শুধু মতামত জানিয়েছি।":"मैंने सिर्फ़ राय बताई है।","এবারের সাফল্য আপনাদের পরিশ্রমের ফলই।":"इस बार की सफलता आप सबके परिश्रम का परिणाम ही है।","ঘটনাটি শুনলে না হেসে থাকতে পারি না।":"घटना सुनने पर न हँसे रह नहीं सकता।","এটি কেবল একটি উদাহরণ।":"यह केवल एक उदाहरण है।"},"lessons.explanation_bn":{"বক্তার দেখা দুটি ঘটনা খুব দ্রুত বদলে যায়। প্রথম অবস্থা বুঝে ওঠার আগেই পরের অবস্থা আসে—এই পরিবর্তনকে তুলে ধরে।":"वक्ता की देखी दो घटनाएँ बहुत जल्दी बदल जाती हैं। पहली स्थिति समझने से पहले ही बाद की स्थिति आती है—इस परिवर्तन को उजागर करता है।","একটি ঘটনা বড় পরিবর্তন, নতুন অভ্যাস বা সম্পর্কের সূচনা করে। শুধু যেকোনো কারণ নয়, শুরু হওয়ার উপলক্ষকে জোর দেয়।":"एक घटना बड़े परिवर्तन, नई आदत या संबंध की शुरुआत करती है। सिर्फ़ कोई भी कारण नहीं, शुरू होने के अवसर पर ज़ोर देता है।","কাজটি করতে সক্ষম হলেও দায়িত্ব, প্রতিশ্রুতি বা সামাজিক কারণে তা করা গ্রহণযোগ্য নয়। নেতিবাচক ক্রিয়ার সঙ্গে “না করে থাকা চলে না”, অর্থাৎ করতেই হবে।":"काम करने में सक्षम होने पर भी दायित्व, प्रतिज्ञा या सामाजिक कारण से वह करना स्वीकार्य नहीं। नकारात्मक क्रिया के साथ \"न करके रहना नहीं चलता\", अर्थात् करना ही होगा।","কোনো শব্দ বা ধারণাকে সামনে এনে তার অর্থ, সংজ্ঞা বা মূল বৈশিষ্ট্য ব্যাখ্যা করুন। প্রবন্ধ ও ব্যাখ্যামূলক লেখায় মানায়।":"किसी शब्द या धारणा को सामने लाकर उसका अर्थ, परिभाषा या मूल लक्षण व्याख्या करें। निबंध और व्याख्यात्मक लेखन में उपयुक्त।","পরিমাণ, ভূমিকা বা গুরুত্বকে সীমিত করে বোঝায়। বক্তা মনে করেন বিষয়টিকে তার চেয়ে বড় করে দেখা ঠিক নয়।":"मात्रा, भूमिका या महत्व को सीमित करके समझाता है। वक्ता मानता है विषय को उससे बड़ा करके देखना ठीक नहीं।","Vた-এর সঙ্গে প্রথম কাজ ভালোভাবে করে তারপর সিদ্ধান্ত বা কাজ করুন। Vる-এর সঙ্গে কোনো কাজের ক্ষেত্রে কী গুরুত্বপূর্ণ তা ব্যাখ্যা করুন।":"Vた के साथ पहला काम अच्छी तरह करके फिर निर्णय या काम करें। Vる के साथ किसी काम के मामले में क्या महत्वपूर्ण है यह व्याख्या करें।","বাস্তবে ঠিক সেই অবস্থা না হলেও তেমন দেখায় বা অনুভূত হয়। কল্পনা ও উপমা তৈরি করতে ব্যবহার করুন।":"वास्तव में ठीक वही स्थिति न होने पर भी वैसा दिखता है या महसूस होता है। कल्पना और उपमा बनाने के लिए उपयोग करें।","পরিচয় বা আসল কারণকে জোর দিয়ে নির্দিষ্ট করে। বক্তা দৃঢ়ভাবে বলেন, এটিই আসল ব্যাখ্যা। আনুষ্ঠানিক যুক্তি বা মূল্যায়নে উপযোগী।":"परिचय या असली कारण पर ज़ोर देकर निर्दिष्ट करता है। वक्ता दृढ़ता से कहता है, यही असली व्याख्या है। औपचारिक तर्क या मूल्यांकन में उपयुक्त।","চাহিদা, ক্ষমতা, পরিস্থিতি বা পরিবর্তনের সঙ্গে সামঞ্জস্য রেখে কাজ বা ব্যবস্থা বদলায়। সবার জন্য একই ব্যবস্থা বোঝায় না।":"माँग, क्षमता, स्थिति या परिवर्तन से सामंजस्य रखकर काम या व्यवस्था बदलती है। सभी के लिए एक ही व्यवस्था नहीं समझाता।","একই বিষয় বা পরিস্থিতির দুটি ভিন্ন দিক পাশাপাশি তুলে ধরে। ভালো-মন্দ, সুবিধা-অসুবিধা বা পরস্পর ভিন্ন প্রবণতা তুলনা করা যায়।":"एक ही विषय या स्थिति के दो भिन्न पहलू साथ-साथ उजागर करता है। अच्छा-बुरा, सुविधा-असुविधा या परस्पर भिन्न प्रवृत्तियों की तुलना की जा सकती है।","একটি বড় পরিবর্তন বা ঘটনার সঙ্গে সম্পর্কিত আরেকটি পরিবর্তন ঘটে। সামাজিক প্রবণতা, নীতি ও সংখ্যা ব্যাখ্যায় উপযোগী।":"एक बड़े परिवर्तन या घटना से संबंधित दूसरा परिवर्तन घटता है। सामाजिक प्रवृत्ति, नीति और संख्या व्याख्या में उपयुक्त।","আগের অবস্থা বা শর্ত বজায় থাকা পর্যন্ত পরের কথা সত্য। 知[し]っている限[かぎ]り বলতে নিজের জানার সীমার মধ্যেও বোঝায়।":"जब तक पिछली स्थिति या शर्त बनी रहती है, तब तक अगली बात सत्य है। 知[し]っている限[かぎ]り का अर्थ अपनी जानकारी की सीमा के भीतर भी होता है।","কারণ বা পরিস্থিতি বিবেচনা করে বক্তা প্রবলভাবে সম্ভাবনা অস্বীকার করেন। এটি বক্তার দৃঢ় বিচার; বৈজ্ঞানিক নিশ্চয়তা দাবি নয়।":"कारण या स्थिति विचार करके वक्ता प्रबलता से संभावना अस्वीकार करता है। यह वक्ता का दृढ़ विचार है; वैज्ञानिक निश्चितता का दावा नहीं।","নিয়ম, তথ্য, গবেষণা বা অভিজ্ঞতাকে সিদ্ধান্তের ভিত্তি হিসেবে ব্যবহার করা হয়। অনুমানের বদলে কী ভিত্তির ওপর কাজ হয়েছে তা বলুন।":"नियम, जानकारी, शोध या अनुभव को निर्णय के आधार के रूप में उपयोग किया जाता है। अनुमान के बदले किस आधार पर काम हुआ है यह कहें।","কাজ বা অবস্থা দীর্ঘ সময়, বিস্তৃত এলাকা বা বহু বিষয়ের পরিসরজুড়ে চলেছে বোঝায়। পরিসরের বিস্তারকে গুরুত্ব দেয়।":"काम या स्थिति लंबे समय, विस्तृत क्षेत्र या कई विषयों के दायरे भर चली है समझाता है। दायरे के विस्तार को महत्व देता है।","অন্য বিকল্প না থাকায় অনিচ্ছা সত্ত্বেও কাজটি করতে হয়। বাইরের পরিস্থিতি বা বাস্তব সীমাবদ্ধতা বক্তাকে বাধ্য করে।":"अन्य विकल्प न होने से अनिच्छा के बावजूद काम करना पड़ता है। बाहरी स्थिति या वास्तविक सीमाबद्धता वक्ता को बाध्य करती है।","আবেগ বা প্রবল স্বাভাবিক তাড়নায় কাজটি না করে থাকা যায় না। নিজের অনুভূতি বা সহজে বোঝা প্রতিক্রিয়া প্রকাশে মানায়।":"भावना या प्रबल स्वाभाविक प्रेरणा से काम न करके रहा नहीं जाता। अपनी भावना या आसानी से समझी प्रतिक्रिया व्यक्त करने में उपयुक्त।","একটি শ্রেণির বাইরে একই কথা আরও বিস্তৃত শ্রেণিতেও প্রযোজ্য হলে ব্যবহার করুন। পরে も বা 広[ひろ]く-এর মতো বিস্তারের ইঙ্গিত থাকতে পারে।":"एक श्रेणी के बाहर वही बात और व्यापक श्रेणी पर भी लागू हो तो इसका उपयोग करें। बाद में も या 広[ひろ]く जैसा विस्तार का संकेत हो सकता है।","আগের তথ্য স্বীকার করেও সীমাবদ্ধতা, ব্যতিক্রম বা সতর্কতা জানান। প্রথম কথাটি মিথ্যা না বলে তাকে শর্তসাপেক্ষ করেন।":"पहली जानकारी स्वीकार करके भी सीमाबद्धता, अपवाद या सावधानी बताएँ। पहली बात को झूठ न कहकर उसे शर्तयुक्त करते हैं।","আগের কাজ ঘটার সঙ্গে সঙ্গেই অপ্রত্যাশিত পরিবর্তন বা ঘটনা ঘটে। পরের অংশে সাধারণত পরিকল্পিত নির্দেশ বা ইচ্ছা থাকে না।":"पहला काम घटने के साथ ही अप्रत्याशित परिवर्तन या घटना घटती है। बाद के भाग में सामान्यतः योजनाबद्ध निर्देश या इच्छा नहीं रहती।","লক্ষণ, পরিস্থিতি বা জানা তথ্য থেকে বক্তা শক্ত অনুমান করেন। সরাসরি দেখা প্রমাণিত ঘটনা বলার বদলে নিজের বিচার প্রকাশ পায়।":"लक्षण, स्थिति या ज्ञात जानकारी से वक्ता मज़बूत अनुमान करता है। सीधे देखी प्रमाणित घटना कहने के बदले अपना विचार प्रकट होता है।","ক্রিয়ার ます বাদ দেওয়া রূপে কোনো কাজ শেষ হলে দ্রুত পরের কাজ করার পরিকল্পনা জানায়। বিশেষ্যের সঙ্গে ফল নির্ভর করার অর্থ হয়।":"क्रिया के ます हटाए रूप में कोई काम समाप्त होने पर जल्दी बाद का काम करने की योजना बताता है। संज्ञा के साथ परिणाम निर्भर करने का अर्थ होता है।","একটি পরিস্থিতি সত্য ধরে নিয়েও পরের মতামত বা সীমা বলুন। জোড়ায় AにしてもBにしても হলে উভয় ক্ষেত্রেই একই কথা প্রযোজ্য।":"एक स्थिति सत्य मानकर भी बाद की राय या सीमा कहें। जोड़ी में AにしてもBにしても होने पर दोनों मामलों में वही बात लागू।","প্রথম বর্ণনাটি পুরো ঠিক নয় মনে করে তার চেয়ে মানানসই দ্বিতীয় বর্ণনা দিন। বিরোধিতা নয়, আরও যথাযথ ভাষায় সংশোধন।":"पहला वर्णन पूरा ठीक नहीं मानकर उससे उपयुक्त दूसरा वर्णन दें। विरोध नहीं, और अधिक यथार्थ भाषा में संशोधन।","একটি কারণকে বিশেষ গুরুত্ব দিয়ে ফলের সঙ্গে জুড়ে দেয়। কারণটি দুর্বল নয়; বক্তা সেটিকেই মূল প্রেরণা হিসেবে সামনে আনছেন।":"एक कारण को विशेष महत्व देकर परिणाम से जोड़ देता है। कारण कमज़ोर नहीं; वक्ता उसे ही मूल प्रेरणा के रूप में सामने ला रहा है।","একটি কাজ বা অবস্থা ঘটানো ছাড়া পরের কাজ ঘটে। লিখিত বা আনুষ্ঠানিক ভাষায় Vないで-এর কাছাকাছি অর্থ।":"एक काम या स्थिति घटाए बिना बाद का काम घटता है। लिखित या औपचारिक भाषा में Vないで के निकट अर्थ।","আগের তথ্য সত্য মেনে নিয়ে পরের অংশে তার প্রত্যাশিত ফল না হওয়ার কথা বলুন। লিখিত বা কিছুটা আনুষ্ঠানিক ব্যাখ্যায় বেশি মানায়।":"पहली जानकारी सत्य मानकर बाद के भाग में उसका अपेक्षित परिणाम न होने की बात कहें। लिखित या कुछ औपचारिक व्याख्या में अधिक उपयुक्त।","নেতিবাচক কথাটিকে পুরোপুরি মানতে চান না। সীমিত সক্ষমতা, আংশিক সত্য বা শর্তসাপেক্ষ সম্মতি প্রকাশ করেন।":"नकारात्मक बात को पूरी तरह नहीं मानना चाहते। सीमित सक्षमता, आंशिक सत्य या शर्तयुक्त सहमति व्यक्त करते हैं।","একটি তুলনার মানদণ্ড নির্দিষ্ট করে পরের তথ্যের পার্থক্য দেখায়। হার, দাম, অতীত ও বর্তমান তুলনায় কাজে আসে।":"एक तुलना का मानदंड निर्दिष्ट करके बाद की जानकारी का अंतर दिखाता है। दर, दाम, भूत और वर्तमान की तुलना में काम आता है।","একটি পরিবর্তন অগ্রসর হওয়ার সঙ্গে অন্য একটি অবস্থাও ধীরে বদলায়। বয়স, সময় বা অভিজ্ঞতার বৃদ্ধি বোঝাতে সুবিধাজনক।":"एक परिवर्तन आगे बढ़ने के साथ दूसरी स्थिति भी धीरे-धीरे बदलती है। उम्र, समय या अनुभव की वृद्धि समझाने में सुविधाजनक।","কাজ বা অনুভূতির লক্ষ্য বোঝায়। দুটি পক্ষের বিপরীত বৈশিষ্ট্য তুলনা করতেও ব্যবহার হয়; কোন ব্যবহার তা প্রসঙ্গ দেখে ধরুন।":"काम या भावना का लक्ष्य समझाता है। दो पक्षों के विपरीत लक्षणों की तुलना करने में भी उपयोग होता है; कौन-सा उपयोग है यह प्रसंग देखकर पकड़ें।","কোনো অভিজ্ঞতা, মাধ্যম বা ব্যক্তির সাহায্যে ফল পাওয়া বোঝায়। সময়ের বিশেষ্যের সঙ্গে পুরো সময়জুড়েও বোঝাতে পারে।":"किसी अनुभव, माध्यम या व्यक्ति की सहायता से परिणाम पाना समझाता है। समय की संज्ञा के साथ पूरे समय भर भी समझा सकता है।","আগের বিষয়টি যাই হোক, পরের ফল বা নিয়ম বদলায় না। বয়স, অভিজ্ঞতা, আবহাওয়া বা অংশগ্রহণের সিদ্ধান্তে ব্যবহার করা যায়।":"पहला विषय जो भी हो, बाद का परिणाम या नियम नहीं बदलता। उम्र, अनुभव, मौसम या भाग लेने के निर्णय में उपयोग किया जा सकता है।","ভবিষ্যতে অনাকাঙ্ক্ষিত ফলের সম্ভাবনা বোঝায়। সংবাদ, সতর্কতা ও আনুষ্ঠানিক ব্যাখ্যায় ব্যবহার হয়।":"भविष्य में अवांछित परिणाम की संभावना समझाता है। समाचार, चेतावनी और औपचारिक व्याख्या में उपयोग होता है।","একটি সাধারণ অনুমান সবার ক্ষেত্রে ঠিক নয়—এই আংশিক নাকচ প্রকাশ করে। কিছু ক্ষেত্রে সত্য হতে পারে, কিন্তু নিশ্চিত নয়।":"एक सामान्य अनुमान सभी के मामले में ठीक नहीं—यह आंशिक नकार व्यक्त करता है। कुछ मामलों में सत्य हो सकता है, लेकिन निश्चित नहीं।","আগেকার অভ্যাস বা বারবার ঘটত এমন অভিজ্ঞতা স্মরণ করে বলুন। এতে স্মৃতিকাতর ভাব থাকতে পারে।":"पहले की आदत या बार-बार घटने वाला ऐसा अनुभव स्मरण करके कहें। इसमें स्मृति-भावुक भाव हो सकता है।"},"lessons.forms":{"必[かなら]ずしも + ইতিবাচক ধারণা + নেতিবাচক predicate":"必[かなら]ずしも + सकारात्मक धारणा + नकारात्मक predicate","Vない・い-বিশেষণくない + ことはない / N・な-বিশেষণでない + ことはない":"Vない・い-विशेषणくない + ことはない / N・な-विशेषणでない + ことはない","Vない-এর ない বাদ + ずにはいられない（する → せずにはいられない）":"Vない का ない हटाकर + ずにはいられない (する → せずにはいられない)","Plain form + からこそ（N・な-বিশেষণ: だ + からこそ）":"Plain form + からこそ (N・な-विशेषण: だ + からこそ)","V・い-বিশেষণ plain + 一方[いっぽう]で / な-বিশেষণ + な一方[いっぽう]で / N + である一方[いっぽう]で":"V・い-विशेषण plain + 一方[いっぽう]で / な-विशेषण + な一方[いっぽう]で / N + である一方[いっぽう]で","সময়・এলাকা・পরিসর N + にわたって / N + にわたる + N":"समय・क्षेत्र・दायरा N + にわたって / N + にわたる + N","Vる・Vている・Vない + 限[かぎ]り / N・な-বিশেষণである + 限[かぎ]り":"Vる・Vている・Vない + 限[かぎ]り / N・な-विशेषणである + 限[かぎ]り","N + とは + সংজ্ঞা・ব্যাখ্যা":"N + とは + परिभाषा・व्याख्या","Plain form + とはいえ（N・な-বিশেষণে だ-ও বাদ যায়）":"Plain form + とはいえ (N・な-विशेषण में だ भी छूटता है)","Vます-stem + 次第[しだい]（সঙ্গে সঙ্গে） / N + 次第[しだい]だ（নির্ভর）":"Vます-stem + 次第[しだい]（तुरंत बाद） / N + 次第[しだい]だ（निर्भर）","Vない-এর ない বাদ + ざるを得[え]ない（する → せざるを得[え]ない）":"Vない का ない हटाकर + ざるを得[え]ない（する → せざるを得[え]ない）","V・い-বিশেষণ plain + かのようだ / N・な-বিশেষণ + であるかのようだ":"V・い-विशेषण plain + かのようだ / N・な-विशेषण + であるかのようだ","V・い-বিশেষণ plain + に違[ちが]いない / N・な-বিশেষণ + に違[ちが]いない":"V・い-विशेषण plain + に違[ちが]いない / N・な-विशेषण + に違[ちが]いない","V・い-বিশেষণ plain + ものの / な-বিশেষণ + なものの / N + であるものの":"V・い-विशेषण plain + ものの / な-विशेषण + なものの / N + であるものの","Vた + ものだ（অতীতের স্মৃতি）":"Vた + ものだ (भूत की स्मृति)","V・い-বিশেষণ plain + わけがない / な-বিশেষণ + なわけがない / N + のわけがない":"V・い-विशेषण plain + わけがない / な-विशेषण + なわけがない / N + のわけがない","Vた + 上[うえ]で（ক্রম） / Vる・Nの + 上[うえ]で（ক্ষেত্র）":"Vた + 上[うえ]で（क्रम） / Vる・Nの + 上[うえ]で（क्षेत्र）","N + に対[たい]して / N + に対[たい]する + N（লক্ষ্য）":"N + に対[たい]して / N + に対[たい]する + N（लक्ष्य）"},"lessons.meaning_bn":{"… করা মাত্রই হঠাৎ":"… करते ही अचानक","একদিকে …, অন্যদিকে …":"एक ओर …, दूसरी ओर …","…এর তুলনায়":"…की तुलना में","যদিও …, তবু …":"हालाँकि …, फिर भी …","…কে সূচনা বা উপলক্ষ করে":"…को शुरुआत या अवसर बनाकर","…অনুযায়ী মানিয়ে":"…के अनुसार ढालकर","…জুড়ে বিস্তৃতভাবে":"…भर विस्तृत रूप से","… বলতে কী বোঝায়":"… कहने से क्या समझा जाता है","… না করেই":"… न करके ही","… বলার চেয়ে বরং …":"… कहने से बल्कि …","একেবারে … নয়, তা নয় / কিছুটা সম্ভব":"बिल्कुल … नहीं, ऐसा नहीं / कुछ हद तक संभव","… নির্বিশেষে":"… के बावजूद/निर्विशेष","…কে ভিত্তি করে":"…को आधार बनाकर","… হলেই সঙ্গে সঙ্গে / …এর ওপর নির্ভর":"… होते ही साथ ही / …पर निर्भर","… না করে উপায় নেই":"… न करके उपाय नहीं","…এর প্রতি / এর বিপরীতে":"…के प्रति / इसके विपरीत","নিশ্চয়ই … হবে, আমার দৃঢ় ধারণা":"निश्चित ही … होगा, मेरी दृढ़ धारणा","… হওয়ার কোনো কথাই নয়":"… होने की कोई बात ही नहीं","ঠিক … বলেই":"ठीक … कहकर ही","… হলো মনে হতেই আবার …":"… हुआ लगते ही फिर …","…এর সঙ্গে সংশ্লিষ্ট পরিবর্তনে":"…से संबंधित परिवर्तन में","এমন বলা গেলেও":"ऐसा कहा जाने पर भी","… করার পরে / … করার ক্ষেত্রে":"… करने के बाद / … करने के मामले में","যতক্ষণ … শর্ত বজায় থাকে":"जब तक … शर्त बनी रहती है","একসময় প্রায়ই … করতাম":"एक समय प्रायः … करता था","…এর মাধ্যমে / …জুড়ে":"…के माध्यम से / …भर","… হলেও / এমনকি … ক্ষেত্রেও":"… होने पर भी / यहाँ तक कि … के मामले में भी","যত …, তত পরিবর্তন":"जितना …, उतना परिवर्तन","… না করে থাকতে পারি না":"… न करके रह नहीं सकता","পরিস্থিতিগত কারণে … করা চলে না":"परिस्थितिगत कारण से … करना नहीं चलता","অন্য কিছু নয়, ঠিক …ই":"अन्य कुछ नहीं, ठीक …ही","মাত্র …, এর বেশি নয়":"मात्र …, इससे अधिक नहीं","শুধু … নয়, অন্যদের ক্ষেত্রেও":"सिर्फ़ … नहीं, दूसरों के मामले में भी","খারাপ কিছু ঘটার আশঙ্কা আছে":"कुछ बुरा घटने की आशंका है","সবসময় বা সবার ক্ষেত্রে … নয়":"हमेशा या सभी के मामले में … नहीं","মনে হয় যেন …":"लगता है जैसे …"},"lessons.quiz.explanation_bn":{"必[かなら]ずしも + とは限[かぎ]らない সাধারণ অনুমানকে আংশিক নাকচ করে।":"必[かなら]ずしも + とは限[かぎ]らない सामान्य अनुमान को आंशिक रूप से नकारता है।","দুটি নেতিবাচক অংশ সীমিত বা শর্তসাপেক্ষ সক্ষমতা প্রকাশ করে।":"दो नकारात्मक भाग सीमित या शर्त-आधारित क्षमता व्यक्त करते हैं।","সংখ্যা কম বা সীমিত হিসেবে দেখাতে にすぎない।":"संख्या को कम या सीमित दिखाने के लिए にすぎない।","する-এর ব্যতিক্রমী ず-রূপ せず।":"する का अपवादात्मक ず-रूप せず।","বিশ্রাম না নিয়ে কাজ চালানোর অর্থে dictionary form + ことなく।":"आराम किए बिना काम जारी रखने के अर्थ में dictionary form + ことなく।","ব্যবহারকারী বাড়ার সঙ্গে সম্পর্ক রেখে সেবা বেড়েছে।":"उपयोगकर्ताओं के बढ़ने के साथ-साथ सेवा भी बढ़ी है।","ব্যর্থতা থেকে নতুন পড়ার পদ্ধতির শুরু হয়েছে।":"असफलता से पढ़ने की नई पद्धति की शुरुआत हुई है।","অভিজ্ঞতা থাকুক বা না থাকুক আবেদন করা যাবে, তাই にかかわらず।":"अनुभव हो या न हो, आवेदन किया जा सकेगा, इसलिए にかかわらず।","প্রথমে আলোচনা শেষ করে পরে সিদ্ধান্ত, তাই Vた + 上[うえ]で।":"पहले चर्चा समाप्त करके बाद में निर्णय, इसलिए Vた + 上[うえ]で।","নদীর পানি উপচে পড়া অনাকাঙ্ক্ষিত সম্ভাবনা, তাই おそれがある।":"नदी के पानी का उफन पड़ना एक अवांछित संभावना है, इसलिए おそれがある।","স্তরের সঙ্গে মিলিয়ে বই বদলায়, তাই に応[おう]じて।":"स्तर के अनुसार किताब बदलती है, इसलिए に応[おう]じて।","উপভাষা কী, তার সংজ্ঞা দেওয়া হচ্ছে।":"बोली क्या है, उसकी परिभाषा दी जा रही है।","বুকিং করার পরও প্রত্যাশিতভাবে যাওয়া হয়নি; ものの এই অমিল দেখায়।":"बुकिंग करने के बाद भी अपेक्षा के अनुसार जाना नहीं हुआ; ものの इस असंगति को दिखाता है।","ব্যর্থ হওয়াটিকেই প্রস্তুতির গুরুত্ব বোঝার বিশেষ কারণ করা হয়েছে।":"असफल होने को ही तैयारी का महत्व समझने का विशेष कारण बनाया गया है।","জানালা খোলার সঙ্গে সঙ্গে অপ্রত্যাশিত বাতাস—Vた + とたん।":"खिड़की खोलते ही अप्रत्याशित हवा—Vた + とたん।","পরিশ্রমের ফলই আসল পরিচয়—এই জোরালো মূল্যায়নে にほかならない।":"परिश्रम का फल ही असली पहचान है—इस दृढ़ मूल्यांकन में にほかならない।","する ব্যতিক্রমীভাবে せざるを得[え]ない হয়।":"する अपवादात्मक रूप से せざるを得[え]ない बनता है।","কাজ ছিল সংস্কৃতি শেখার মাধ্যম, তাই を通[とお]して।":"काम संस्कृति सीखने का माध्यम था, इसलिए を通[とお]して।","শিক্ষার্থী ছাড়াও শিক্ষক অংশ নেন; সীমা বিস্তৃত হচ্ছে, তাই に限[かぎ]らず।":"छात्रों के अलावा शिक्षक भी भाग लेते हैं; सीमा विस्तृत हो रही है, इसलिए に限[かぎ]らず।","終[お]わります থেকে ます বাদ দিয়ে 次第[しだい]; কাজ শেষ হলেই পরিকল্পিত যোগাযোগ।":"終[お]わります से ます हटाकर 次第[しだい]; काम समाप्त होते ही नियोजित संपर्क।","সস্তা হওয়া মেনেও কেনার সীমা দেখাচ্ছে।":"सस्ता होना मानते हुए भी खरीदने की सीमा दिखा रहा है।","ব্যাখ্যার ভিত্তি হবে ঘটনা বা তথ্য, তাই に基[もと]づいて।":"व्याख्या का आधार घटना या तथ्य होगा, इसलिए に基[もと]づいて।","ফিরে আসার পরপরই আবার বের হওয়া—দ্রুত অবস্থা বদলাচ্ছে।":"लौटने के तुरंत बाद फिर बाहर जाना—स्थिति तेज़ी से बदल रही है।","কথা বলার ধরনকে উপমা দিয়ে বর্ণনা করায় かのように।":"बोलने के ढंग का उपमा देकर वर्णन करने के कारण かのように।","関心[かんしん] বিশেষ্যকে বর্ণনা করছে, তাই に対[たい]する।":"関心[かんしん] संज्ञा का वर्णन कर रहा है, इसलिए に対[たい]する।","শান্ত হওয়া ও যাতায়াত অসুবিধা—দুটি ভিন্ন দিক, তাই 一方[いっぽう]で।":"शांत होना और आवागमन की असुविधा—दो अलग पहलू हैं, इसलिए 一方[いっぽう]で।","অভিজ্ঞতা বাড়ার সঙ্গে আত্মবিশ্বাস বাড়ছে—পরিবর্তনের সহগতি।":"अनुभव बढ़ने के साथ आत्मविश्वास बढ़ रहा है—परिवर्तन की सहगति।","রাগের বর্ণনা বদলে বিপাকে পড়াকে বেশি যথাযথ বলা হচ্ছে।":"क्रोध के वर्णन के बजाय मुसीबत में पड़ने को अधिक उचित कहा जा रहा है।","এখানে বসবাসের শর্ত বজায় থাকাকালীন নিয়ম মানতে হবে।":"यहाँ निवास की शर्त बनी रहने तक नियमों का पालन करना होगा।","ব্যস্ততা মেনেও যোগাযোগের প্রয়োজন বোঝানো হয়েছে।":"व्यस्तता मानते हुए भी संपर्क की आवश्यकता समझाई गई है।","দুই সপ্তাহজুড়ে সাক্ষাৎকার নেওয়ার বিস্তার বোঝাচ্ছে।":"दो सप्ताह भर साक्षात्कार लेने का विस्तार समझा रहा है।","আলো জ্বলছে দেখে কেউ আছেন বলে দৃঢ় অনুমান করা হয়েছে।":"रोशनी जलती देखकर कोई है, ऐसा दृढ़ अनुमान लगाया गया है।","এটি দেরি করার সামর্থ্যের প্রশ্ন নয়; গুরুত্বপূর্ণ সভায় দেরি করা চলে না।":"यह देर करने की क्षमता का प्रश्न नहीं है; महत्वपूर्ण बैठक में देर नहीं की जा सकती।","গত মাস হচ্ছে তুলনার ভিত্তিকাল, তাই に比[くら]べて।":"पिछला महीना तुलना का आधार-काल है, इसलिए に比[くら]べて।","অতীতের পুনরাবৃত্ত অভ্যাস স্মরণ করতে Vた + ものだ।":"अतीत की बार-बार की आदत को याद करने के लिए Vた + ものだ।","কোনোভাবেই বলার কথা নয়—দৃঢ় অস্বীকারে わけがない।":"किसी भी तरह कहने की बात नहीं है—दृढ़ इनकार में わけがない।"},"lessons.quiz.options":{"পড়তে একেবারে পারি না, তা নয়":"ऐसा नहीं है कि मैं बिल्कुल नहीं पढ़ सकता।","একেবারেই পড়তে পারি না":"बिल्कुल भी नहीं पढ़ सकता।","অবশ্যই নিখুঁতভাবে পড়ি":"अवश्य ही पूरी तरह सही ढंग से पढ़ता हूँ।"},"lessons.quiz.prompt":{"দৃঢ় অস্বীকার:「彼[かれ]がそんなことを言[い]う（　）。」":"दृढ़ इनकार:「彼[かれ]がそんなことを言[い]う（　）。」","「読[よ]めないことはない。」—কোন অর্থ?":"「読[よ]めないことはない。」—कौन-सा अर्थ है?","「二週間[にしゅうかん]（　）、社員[しゃいん]に話[はなし]を聞[き]いた。」—সময়ের বিস্তার।":"「二週間[にしゅうかん]（　）、社員[しゃいん]に話[はなし]を聞[き]いた。」—समय का विस्तार।","する-এর সঠিক রূপ:「心配[しんぱい]（　）にはいられない。」":"する का सही रूप:「心配[しんぱい]（　）にはいられない。」","「失敗[しっぱい]（　）、勉強[べんきょう]の方法[ほうほう]を変[か]えた。」—পরিবর্তনের সূচনা।":"「失敗[しっぱい]（　）、勉強[べんきょう]の方法[ほうほう]を変[か]えた。」—परिवर्तन की शुरुआत।","「仕事[しごと]（　）、地域[ちいき]の文化[ぶんか]を学[まな]んだ。」—মাধ্যম।":"「仕事[しごと]（　）、地域[ちいき]の文化[ぶんか]を学[まな]んだ。」—माध्यम।","「成功[せいこう]は努力[どりょく]の結果[けっか]（　）。」—দৃঢ় মূল্যায়ন।":"「成功[せいこう]は努力[どりょく]の結果[けっか]（　）。」—दृढ़ मूल्यांकन।","「先月[せんげつ]（　）、売上[うりあげ]が下[さ]がった。」—তুলনা।":"「先月[せんげつ]（　）、売上[うりあげ]が下[さ]がった。」—तुलना।","দৃঢ় অনুমান:「電気[でんき]がついている。誰[だれ]かいる（　）。」":"दृढ़ अनुमान:「電気[でんき]がついている。誰[だれ]かいる（　）。」","「すべて分[わ]かっている（　）話[はな]す。」—যেন সব জানে।":"「すべて分[わ]かっている（　）話[はな]す。」—जैसे सब कुछ जानता हो।","「大雨[おおあめ]で川[かわ]があふれる（　）。」—অনাকাঙ্ক্ষিত ঝুঁকি।":"「大雨[おおあめ]で川[かわ]があふれる（　）。」—अवांछित जोखिम।","「忙[いそが]しい（　）、連絡[れんらく]は必要[ひつよう]だ。」—শর্ত মেনে সীমা।":"「忙[いそが]しい（　）、連絡[れんらく]は必要[ひつよう]だ。」—शर्त स्वीकार करते हुए सीमा।","「環境[かんきょう]問題[もんだい]（　）関心[かんしん]が高[たか]い。」—লক্ষ্যবিষয়।":"「環境[かんきょう]問題[もんだい]（　）関心[かんしん]が高[たか]い。」—लक्ष्य विषय।","শেষ হলেই জানাব:「終[お]わり（　）、連絡[れんらく]します。」":"समाप्त होते ही सूचना दूँगा:「終[お]わり（　）、連絡[れんらく]します。」","「経験[けいけん]が増[ふ]える（　）、自信[じしん]もつく。」—ক্রমে পরিবর্তন।":"「経験[けいけん]が増[ふ]える（　）、自信[じしん]もつく。」—क्रमशः परिवर्तन।","「失敗[しっぱい]した（　）、次[つぎ]は準備[じゅんび]を大切[たいせつ]にする。」—কারণে জোর।":"「失敗[しっぱい]した（　）、次[つぎ]は準備[じゅんび]を大切[たいせつ]にする。」—कारण पर ज़ोर।","「この町[まち]は静[しず]かな（　）、交通[こうつう]が不便[ふべん]です。」—দুটি দিক।":"「この町[まち]は静[しず]かな（　）、交通[こうつう]が不便[ふべん]です。」—दो पहलू।","「休[やす]む（　）、作業[さぎょう]を続[つづ]けた。」—না করে।":"「休[やす]む（　）、作業[さぎょう]を続[つづ]けた。」—किए बिना।","আগে আলোচনা, তারপর সিদ্ধান্ত:「相談[そうだん]（　）上[うえ]で、決[き]めます。」":"पहले चर्चा, फिर निर्णय:「相談[そうだん]（　）上[うえ]で、決[き]めます。」","「学生[がくせい]（　）、先生[せんせい]も参加[さんか]します。」—শিক্ষার্থীর বাইরেও প্রযোজ্য।":"「学生[がくせい]（　）、先生[せんせい]も参加[さんか]します。」—छात्रों के अलावा भी लागू।","「帰[かえ]ってきた（　）、また出[で]かけた。」—দ্রুত পালাবদল।":"「帰[かえ]ってきた（　）、また出[で]かけた。」—तेज़ बदलाव।","する-এর সঠিক রূপ:「中止[ちゅうし]（　）を得[え]ない。」":"する का सही रूप:「中止[ちゅうし]（　）を得[え]ない。」","「レベル（　）、教材[きょうざい]を変[か]えます。」—মানিয়ে নেওয়া।":"「レベル（　）、教材[きょうざい]を変[か]えます。」—अनुकूल बनाना।","সংজ্ঞা:「方言[ほうげん]（　）、ある地域[ちいき]で使[つか]われる言葉[ことば]だ。」":"परिभाषा:「方言[ほうげん]（　）、ある地域[ちいき]で使[つか]われる言葉[ことば]だ。」","「事実[じじつ]（　）、説明[せつめい]してください。」—ভিত্তি।":"「事実[じじつ]（　）、説明[せつめい]してください。」—आधार।","「怒[おこ]っている（　）、困[こま]っているようだ。」—আরও যথাযথ বর্ণনা।":"「怒[おこ]っている（　）、困[こま]っているようだ。」—अधिक उचित वर्णन।","পুরোনো অভ্যাস:「学生時代[がくせいじだい]は、よく図書館[としょかん]へ（　）ものだ。」":"पुरानी आदत:「学生時代[がくせいじだい]は、よく図書館[としょかん]へ（　）ものだ。」","「大切[たいせつ]な会議[かいぎ]なので、遅[おく]れる（　）。」—দায়িত্ববোধ।":"「大切[たいせつ]な会議[かいぎ]なので、遅[おく]れる（　）。」—दायित्व-बोध।","「参加者[さんかしゃ]は十人[じゅうにん]（　）。」—মাত্র দশজন।":"「参加者[さんかしゃ]は十人[じゅうにん]（　）。」—मात्र दस लोग।"},"lessons.tip_bn":{"する-এর রূপ せざる; しざる নয়। নিজের আগ্রহে পছন্দ করা কাজের জন্য নয়।":"する का रूप せざる; しざる नहीं। अपनी रुचि से चुने काम के लिए नहीं।","わけではない = পুরোপুরি এমন নয়; わけがない = কোনোভাবেই এমন হওয়ার কথা নয়।":"わけではない = पूरी तरह ऐसा नहीं; わけがない = किसी भी तरह ऐसा होने की बात नहीं।","এই পাঠে সংজ্ঞার ব্যবহার; とは思[おも]わなかった-তে বিস্ময়ের ব্যবহার আলাদা।":"इस पाठ में परिभाषा का प्रयोग है; とは思[おも]わなかった में आश्चर्य का प्रयोग अलग है।","কারণ জানাতে からにほかならない; শুধু বিশেষ্যের পরিচয় জোর দিতে にほかならない।":"कारण बताने के लिए からにほかならない; सिर्फ़ संज्ञा के परिचय पर ज़ोर देने के लिए にほかならない।","অভিজ্ঞতার মাধ্যমে শেখা এবং সারা বছরজুড়ে—এই দুই ব্যবহার প্রসঙ্গ দেখে আলাদা করুন।":"अनुभव के माध्यम से सीखना और पूरे वर्ष भर—इन दो उपयोगों को प्रसंग देखकर अलग करें।","যদিও গ্রীষ্ম, তবু পাহাড়ে ঠান্ডা—এই ধরনের স্বীকারের পর সীমা দেখায়।":"हालाँकि गर्मी, फिर भी पहाड़ पर ठंड—इस प्रकार की स्वीकृति के बाद सीमा दिखाता है।","だけでなく-এর মতো বিস্তার বোঝায়; “এই সময়ের মধ্যে সীমাবদ্ধ” অর্থের に限[かぎ]り আলাদা।":"だけでなく की तरह विस्तार दर्शाता है; “इस समय के भीतर सीमित” अर्थ वाला に限[かぎ]り अलग है।","জোরপূর্বক বাইরের বাধ্যবাধকতা নয়; হাসি, চিন্তা, কান্নার মতো ভেতরের তাড়না প্রধান।":"ज़बरदस्ती बाहरी बाध्यता नहीं; हँसी, चिंता, रोने जैसी अंदर की प्रेरणा मुख्य।","に応[おう]じて শর্ত অনুযায়ী বদলায়; にかかわらず শর্তে বদলায় না।":"に応[おう]じて शर्त के अनुसार बदलता है; にかかわらず शर्त से नहीं बदलता।","遅[おく]れるにしても মানে দেরি হলেও; দেরি করার অনুমতি দেওয়া নয়।":"遅[おく]れるにしても का अर्थ है देर हो भी जाए तो; देर करने की अनुमति देना नहीं है।","দুটি ঘটনা শুধু পাশাপাশি নয়; সম্পর্কিত পরিবর্তন দেখাতে হবে।":"दो घटनाएँ सिर्फ़ साथ-साथ नहीं; संबंधित परिवर्तन दिखाना होगा।","食[た]べられないことはない = খাওয়া একেবারে অসম্ভব নয়; স্বচ্ছন্দে খেতে পারি এমন জোর নেই।":"食[た]べられないことはない = खाना बिल्कुल असंभव नहीं है; आराम से खा सकता हूँ, ऐसा ज़ोर नहीं है।","নিয়মিত “এর পরে” বলার জন্য てから যথেষ্ট; とたん হঠাৎ ঘটার অনুভূতি দেয়।":"नियमित \"इसके बाद\" कहने के लिए てから पर्याप्त; とたん अचानक घटने की भावना देता है।","কিসের সঙ্গে তুলনা করছেন তা পরিষ্কার রাখুন; শুধু সংখ্যা বললেই তুলনা সম্পূর্ণ হয় না।":"किसके साथ तुलना कर रहे हैं यह स्पष्ट रखें; सिर्फ़ संख्या कहने से तुलना पूर्ण नहीं होती।","পরের বিশেষ্যকে বর্ণনা করলে かのようなN; ক্রিয়াকে বর্ণনা করলে かのようにV।":"बाद की संज्ञा का वर्णन करने पर かのようなN; क्रिया का वर्णन करने पर かのようにV।","রূপ বদলালে অর্থ বদলায়: 確認[かくにん]した上[うえ]で = যাচাইয়ের পরে; 働[はたら]く上[うえ]で = কাজ করার ক্ষেত্রে।":"रूप बदलने से अर्थ बदलता है: 確認[かくにん]した上[うえ]で = जाँच के बाद; 働[はたら]く上[うえ]で = काम करने के क्षेत्र में।","মাত্র তিনজন = 三人[さんにん]にすぎない; প্রায় তিনজন = 三人[さんにん]ぐらい—অর্থ আলাদা।":"मात्र तीन लोग = 三人[さんにん]にすぎない; लगभग तीन लोग = 三人[さんにん]ぐらい—अर्थ अलग है।","আগের ঘটনাটি পরের পরিবর্তনের শুরু; দৈনন্দিন ছোট কারণেও সবসময় ব্যবহার করবেন না।":"पहली घटना बाद के परिवर्तन की शुरुआत है; दैनिक छोटे कारणों में भी हमेशा उपयोग न करें।","Vる + 一方[いっぽう]だ শুধু পরিবর্তন এক দিকেই এগোনো বোঝাতে পারে; এই পাঠে শেষে で আছে।":"Vる + 一方[いっぽう]だ केवल परिवर्तन का एक ही दिशा में आगे बढ़ना दर्शा सकता है; इस पाठ में अंत में で है।","বাক্যের পরের অংশে আগের শর্ত অনুযায়ী মানিয়ে নেওয়ার সম্পর্ক খুঁজুন।":"वाक्य के बाद के भाग में पहली शर्त के अनुसार ढालने का संबंध खोजें।","から সাধারণ কারণ, からこそ সেই কারণকে জোর দেয়। পরে ইতিবাচক উপদেশ বা মূল্যায়ন প্রায়ই আসে।":"から सामान्य कारण, からこそ उस कारण पर ज़ोर देता है। बाद में सकारात्मक उपदेश या मूल्यांकन प्रायः आता है।","নিশ্চয়তা অনুভব করলেও এটি অনুমান; হুবহু “প্রমাণিত সত্য” নয়।":"निश्चितता महसूस करने पर भी यह अनुमान है; हूबहू \"प्रमाणित सत्य\" नहीं।","সাধারণ “ভাবছি” অর্থ নয়। দ্রুত পালাবদল; নিজের ইচ্ছাকৃত ধারাবাহিক কাজ বোঝাতে কম মানায়।":"सामान्य \"सोच रहा हूँ\" अर्थ नहीं। तेज़ बदलाव; अपने इच्छापूर्ण निरंतर काम समझाने में कम उपयुक्त।","সরাসরি dictionary form লাগে: 休[やす]むことなく; 休[やす]まないことなく লিখবেন না।":"सीधे dictionary form लगता है: 休[やす]むことなく; 休[やす]まないことなく न लिखें।","এই পাঠে শর্তের ব্যবহার। 時間[じかん]の限[かぎ]り মানে সময়ের শেষ সীমা পর্যন্ত—প্রসঙ্গ আলাদা।":"इस पाठ में शर्त का प्रयोग है। 時間[じかん]の限[かぎ]り का अर्थ है समय की अंतिम सीमा तक—संदर्भ अलग है।","পরের অংশে পরিবর্তন দিন; একটি নির্দিষ্ট মুহূর্তের সিদ্ধান্ত বা সরাসরি আদেশ মানায় না।":"बाद के भाग में परिवर्तन दें; एक निर्दिष्ट क्षण का निर्णय या सीधा आदेश उपयुक्त नहीं।","終[お]わり次第[しだい] = শেষ হলেই; 天気[てんき]次第[しだい] = আবহাওয়ার ওপর নির্ভর।":"終[お]わり次第[しだい] = समाप्त होते ही; 天気[てんき]次第[しだい] = मौसम पर निर्भर।","ভালো ফলের সম্ভাবনায় সাধারণত使[つか]わない; 危険[きけん] বা ক্ষতির পূর্বাভাসে মানায়।":"अच्छे परिणाम की संभावना में आमतौर पर 使[つか]わない; 危険[きけん] या हानि की भविष्यवाणी में यह उपयुक्त होता है।","একবারের সাম্প্রতিক ঘটনা নয়। ものだ-এর সাধারণ সত্য বা উপদেশের ব্যবহার থেকে এটি আলাদা।":"एक बार की हाल की घटना नहीं। ものだ के सामान्य सत्य या उपदेश के उपयोग से यह अलग है।","সরাসরি অক্ষমতা できない থেকে আলাদা। 休[やす]まないわけにはいかない মানে বিশ্রাম নিতেই হবে।":"सीधी असमर्थता できない से अलग है। 休[やす]まないわけにはいかない का अर्थ है आराम करना ही होगा।","একটি নির্দিষ্ট মুহূর্তের জন্য নয়। 一時間[いちじかん]にわたる説明[せつめい] মানে এক ঘণ্টাজুড়ে ব্যাখ্যা।":"किसी एक निश्चित क्षण के लिए नहीं है। 一時間[いちじかん]にわたる説明[せつめい] का अर्थ है एक घंटे भर की व्याख्या।","দুটি বিকল্পের মধ্যে দ্বিতীয়টি বেশি সঠিক—এই দিকটি খেয়াল রাখুন।":"दो विकल्पों में दूसरा अधिक सही—इस पहलू का ध्यान रखें।","পুরোপুরি অসম্ভব অর্থ নয়। 必[かなら]ずしも-এর সঙ্গে শেষে নেতিবাচক অর্থ রাখুন।":"पूरी तरह असंभव का अर्थ नहीं है। 必[かなら]ずしも के साथ अंत में नकारात्मक अर्थ रखें।","বিশেষ্যের আগে に対[たい]する: 先生[せんせい]に対[たい]する質問[しつもん]।":"संज्ञा से पहले に対[たい]する: 先生[せんせい]に対[たい]する質問[しつもん]।","単[たん]に “অনুযায়ী” নয়; সিদ্ধান্তের ভিত্তির সঙ্গে দৃঢ় সম্পর্ক আছে।":"単[たん]に “अनुसार” नहीं है; निर्णय के आधार के साथ इसका दृढ़ संबंध है।","ものの-এর পরে বাস্তব ফল বা অবস্থা দিন। শুধু দুটি কাজের ক্রম বোঝাতে ব্যবহার করবেন না।":"ものの के बाद वास्तविक परिणाम या स्थिति दें। सिर्फ़ दो कामों का क्रम समझाने के लिए उपयोग न करें।"},"scope_bn":{"QUARTET II-এর ৭–১২ অধ্যায়ের থিম অনুসরণে নির্বাচিত ৩৬টি গ্রামারের নিজস্ব সহায়ক অনুশীলন। এটি মূল বইয়ের সম্পূর্ণ গ্রামার সূচি নয়।":"QUARTET II के 7–12 अध्यायों के थीम का अनुसरण करके चयनित 36 व्याकरणों का अपना सहायक अभ्यास। यह मूल किताब की पूर्ण व्याकरण सूची नहीं है।"},"study.dialogue":{"ঠিক বলেছেন। এখনই যোগাযোগ করে দেখব।":"सही कहा। अभी संपर्क करके देखूँगा।","হ্যাঁ। যাচাই করার পরে সিদ্ধান্ত নিই।":"हाँ। जाँचने के बाद निर्णय लें।","নির্দেশনার কাগজ বাড়ালে কেমন হয়?":"निर्देश का कागज़ बढ़ाने पर कैसा होगा?","আজ আপনার বাসায় আসতে পারি?":"आज आपके घर आ सकता हूँ?","কিছু হয়েছে?":"कुछ हुआ है?","গ্রাহকসেবার ক্ষেত্রে কোন বিষয়কে গুরুত্ব দেন?":"ग्राहक सेवा के मामले में किस विषय को महत्व देते हैं?","আচ্ছা। তাহলে সুবিধামতো একটি দিন জানাবেন?":"अच्छा। तो सुविधानुसार एक दिन बताएँगे?","আগামীকাল একটু সাহায্য করবেন?":"कल थोड़ी सहायता करेंगे?","আগে ব্যবহারকারীদের জিজ্ঞেস করে দেখব?":"पहले उपयोगकर्ताओं से पूछकर देखूँ?","এই গ্রাফ থেকে কী বোঝা যায়?":"इस ग्राफ़ से क्या समझा जाता है?","রবিবার হলে পারব।":"रविवार होने पर सकूँगा।","এটিও একটি উপায়, তবে ভাষা বদলানোর প্রয়োজনও আছে বলে মনে করি।":"यह भी एक उपाय है, लेकिन भाषा बदलने की आवश्यकता भी है ऐसा मानता हूँ।","তাহলে রবিবার হলে কেমন হয়?":"तो रविवार होने पर कैसा होगा?","প্রথমে গ্রাহকের চাহিদা নিশ্চিত করি।":"पहले ग्राहक की माँग निश्चित करता हूँ।","স্টেশনে খোঁজ নিয়ে দেখলে কেমন হয়?":"स्टेशन पर पूछताछ करके देखने पर कैसा होगा?","কিছু কথা জিজ্ঞেস করতে পারি?":"कुछ बात पूछ सकता हूँ?","একটি গুরুত্বপূর্ণ খাতা হারিয়ে ফেলেছি।":"एक महत्वपूर्ण कॉपी खो दी है।","আগামীকাল কাজ আছে বলে পারব না।":"कल काम है कहकर नहीं सकूँगा।","দুঃখিত, আজ আমার অন্য কাজ আছে।":"क्षमा करें, आज मेरा अन्य काम है।","অন্য স্কুলেও কি একই রকম হবে?":"अन्य स्कूलों में भी क्या ऐसा ही होगा?","ট্রেন ব্যবহারকারী সবচেয়ে বেশি।":"ट्रेन उपयोगकर्ता सबसे अधिक।","জি, বলুন।":"जी, कहें।","শনিবার বিকেল হলে ঠিক আছে।":"शनिवार दोपहर बाद होने पर ठीक है।","শুধু এই জরিপ থেকে তা বিচার করা যায় না।":"सिर्फ़ इस सर्वेक्षण से वह विचार नहीं किया जा सकता।"},"study.kanji":{"বোঝা বা সমাধান":"समझना या समाधान","তুলনা":"तुलना","দৃশ্য":"दृश्य","প্রত্যাশা":"अपेक्षा","বৃদ্ধি":"वृद्धि","মিলিত সহযোগিতা":"मिलित सहयोग","বাহিরে প্রকাশ":"बाहर प्रकट","অনুভূতি বা অবস্থা":"भावना या स्थिति","অতিথি বা ক্রেতা":"अतिथि या क्रेता","অভ্যস্ত":"अभ्यस्त","মনের ভাব":"मन का भाव","ধারণা বা চিন্তা":"धारणा या सोच","বদলানো":"बदलना","বিবেচনা":"विचार","ভিন্ন":"भिन्न","ভরসা":"भरोसा","হ্রাস":"कमी","রূপ বা ছাপ":"रूप या छाप"},"study.listening_answer":{"এ সপ্তাহে প্রশ্ন তৈরি হবে; আগামী সপ্তাহে লাইব্রেরির প্রবেশপথে জরিপ হবে।":"इस सप्ताह प्रश्न बनेंगे; अगले सप्ताह पुस्तकालय के प्रवेश द्वार पर सर्वेक्षण होगा।","জীবনবৃত্তান্ত আনতে হবে; আগামী মঙ্গলবার বেলা ৩টার মধ্যে অফিসে আসতে হবে; পরিবর্তন চাইলে আগের দিনের মধ্যে ফোন করতে হবে।":"जीवनवृत्त लाना होगा; अगले मंगलवार दोपहर 3 बजे तक कार्यालय आना होगा; परिवर्तन चाहने पर पिछले दिन तक फ़ोन करना होगा।","শনিবার বেলা ২টা; স্টেশনের সামনের লাইব্রেরি; শুক্রবারের মধ্যে জানাতে হবে।":"शनिवार दोपहर 2 बजे; स्टेशन के सामने की लाइब्रेरी; शुक्रवार तक बताना होगा।","মঙ্গলবার বিকেলে পারবেন; সময়সূচি বদলানো যাবে কি না যাচাই করতে বলছেন।":"मंगलवार दोपहर बाद सकेगा; समय-सारणी बदली जा सकेगी या नहीं जाँचने को कह रहा है।","সকালে ৬÷১০ = ৬০ শতাংশ; নির্দিষ্ট সময় নেই একজনের। এগুলো অনুশীলনের সংখ্যা।":"सुबह 6÷10 = 60 प्रतिशत; निर्दिष्ट समय नहीं एक व्यक्ति का। ये अभ्यास की संख्याएँ हैं।","গতকাল দোকানে যে আসনে বসেছিলেন সেখানে; আজ সন্ধ্যায় নিতে যাবেন।":"कल दुकान में जिस आसन पर बैठा था वहाँ; आज शाम लेने जाएगा।"},"study.listening_question":{"ব্যাগ কোথায় পাওয়া গেছে? বক্তা কখন নিতে যাবেন?":"बैग कहाँ मिला है? वक्ता कब लेने जाएगा?","কী আনতে হবে, কখন আসতে হবে, পরিবর্তন চাইলে কী করবেন?":"क्या लाना होगा, कब आना होगा, परिवर्तन चाहने पर क्या करेंगे?","সকালে পড়ার অনুপাত কত? নির্দিষ্ট সময় নেই কতজনের?":"सुबह पढ़ने का अनुपात कितना? निर्दिष्ट समय नहीं कितने लोगों का?","কখন, কোথায় এবং কত দিনের মধ্যে জানাতে হবে?":"कब, कहाँ और कितने दिनों के भीतर बताना होगा?","এ সপ্তাহে কী হবে? জরিপ কোথায় এবং কখন হবে?":"इस सप्ताह क्या होगा? सर्वेक्षण कहाँ और कब होगा?","বক্তা কোন দিন পারবেন? শ্রোতার কাছে কী অনুরোধ করছেন?":"वक्ता किस दिन सकेगा? श्रोता से क्या अनुरोध कर रहा है?"},"study.questions":{"সবার কাছে একই ব্যাখ্যা যথেষ্ট নয় কেন?":"सभी के लिए एक ही व्याख्या पर्याप्त क्यों नहीं?","মিনা যাওয়ার আগে কী করেনি?":"मीना जाने से पहले क्या नहीं किया?","গ্রাহকের প্রয়োজন অনুযায়ী ব্যাখ্যা মানিয়ে নেওয়া।":"ग्राहक की आवश्यकता के अनुसार व्याख्या ढालना।","প্রথমবার আসা ব্যক্তির উদাহরণটি কী বোঝায়?":"पहली बार आए व्यक्ति का उदाहरण क्या समझाता है?","দৃষ্টিকোণ বদলানোর কারণ কী ছিল?":"दृष्टिकोण बदलने का कारण क्या था?","লেখাটির মূল শিক্ষা কী?":"लेख की मूल शिक्षा क्या है?","পরের বাক্যে কাজ থাকার কারণ ও রবিবারের বিকল্প দেওয়ার তথ্য থেকে।":"बाद के वाक्य में काम होने का कारण और रविवार का विकल्प देने की जानकारी से।","ট্রেন ব্যবহারকারীর অনুপাত কত এবং কীভাবে পেলেন?":"ट्रेन उपयोगकर्ताओं का अनुपात कितना है और कैसे पाया?","প্রথমে কাগজ বাড়াতে চেয়েছিল; পরে ব্যবহারকারীর প্রয়োজন বুঝে ভাষা সহজ করেছে।":"पहले कागज़ बढ़ाना चाहा था; बाद में उपयोगकर्ता की आवश्यकता समझकर भाषा आसान की है।","খাতা পাওয়া গেছে বলে স্টেশনের খবর আসার পর।":"कॉपी मिल गई है कहकर स्टेशन की खबर आने के बाद।","না; আগামীকাল পারবে না, রবিবার পারবে বলে বিকল্প দিয়েছে।":"नहीं; कल नहीं सकेगा, रविवार सकेगा कहकर विकल्प दिया है।","ব্যবহারকারীদের সঙ্গে কথা বলে সমস্যাটি শ্রেণিবিভাগের নাম বুঝতে অসুবিধা বলে জানা যায়।":"उपयोगकर्ताओं से बात करके समस्या वर्गीकरण के नाम समझने में कठिनाई है यह ज्ञात होता है।","আমন্ত্রণের ভাষা শুনে সময় ধরে না নিয়ে পরিস্থিতি যাচাই ও আলোচনা করা দরকার।":"निमंत्रण की भाषा सुनकर समय मान न लेकर स्थिति की जाँच और चर्चा करना ज़रूरी है।","১২÷২০×১০০ = ৬০ শতাংশ।":"12÷20×100 = 60 प्रतिशत।","কোন ঘটনায় ইউয়ের অনুভূতি বদলাল?":"किस घटना से यू की भावना बदली?","প্রথম প্রস্তাব ও শেষ পদক্ষেপ কীভাবে আলাদা?":"पहला प्रस्ताव और अंतिम कदम कैसे अलग हैं?","গ্রাহকের অভিজ্ঞতা ও চাহিদা আলাদা; সে অনুযায়ী ক্রম ও ভাষা বদলাতে হয়।":"ग्राहक का अनुभव और माँग अलग; उसके अनुसार क्रम और भाषा बदलनी पड़ती है।","না; খাতা হারিয়ে ইউয়ের অনুভূতির উপমা। かのように সূত্রটি দেখুন।":"नहीं; कॉपी खोकर यू की भावना की उपमा। かのように सूत्र देखें।","কথাগুলো মুছে যাওয়ার বর্ণনাটি কি বাস্তব ঘটনা?":"बातें मिट जाने का वर्णन क्या वास्तविक घटना है?","বন্ধুর সময় আছে কি না যোগাযোগ করে নিশ্চিত করেনি। দ্বিতীয় ও তৃতীয় বাক্য মিলিয়ে বুঝবেন।":"दोस्त के पास समय है या नहीं संपर्क करके निश्चित नहीं किया। दूसरा और तीसरा वाक्य मिलाकर समझेंगे।","難[むずか]しい-এর উদ্দেশ্য কোন তথ্য থেকে নিশ্চিত হলেন?":"難[むずか]しい का उद्देश्य किस जानकारी से निश्चित हुआ?","এই কথোপকথনে বন্ধু কি সাহায্য একেবারে অস্বীকার করেছে?":"इस बातचीत में दोस्त ने क्या सहायता बिल्कुल अस्वीकार की है?","উত্তরদাতা কেবল একটি ক্লাসের ২০ জন; নমুনা জাতীয় প্রতিনিধিত্ব নিশ্চিত করে না।":"उत्तरदाता केवल एक कक्षा के 20 लोग; नमूना राष्ट्रीय प्रतिनिधित्व निश्चित नहीं करता।","কেন সারা জাপানের বিষয়ে সিদ্ধান্ত নেওয়া যায় না?":"क्यों पूरे जापान के विषय में निर्णय नहीं लिया जा सकता?"},"study.reading":{"たとえば-এর উদাহরণ আগের মানিয়ে নেওয়ার বক্তব্যকে স্পষ্ট করে।":"たとえば का उदाहरण पिछले ढालने के कथन को स्पष्ट करता है।","পরের কারণ ও বিকল্প দিন থেকে আগের কথার উদ্দেশ্য পরিষ্কার হয়।":"बाद के कारण और वैकल्पिक दिन से पहली बात का उद्देश्य स्पष्ट होता है।","অন্য দৃষ্টিকোণ থেকে ভাবাই উন্নতির সূচনা হলো।":"दूसरे दृष्टिकोण से सोचना ही उन्नति की शुरुआत हुई।","একটি ছোট দোকানের ম্যানেজারকে জিজ্ঞেস করলাম, কাজের কোন বিষয়টিকে গুরুত্ব দেন।":"एक छोटी दुकान के मैनेजर से पूछा, काम के किस विषय को महत्व देते हैं।","কাগজ কম থাকা নয়, নামের অর্থ না বোঝা—সমস্যার ব্যাখ্যা বদলাল।":"कागज़ कम होना नहीं, नाम का अर्थ न समझना—समस्या की व्याख्या बदली।","এই বাক্য গল্পের মোড় বদলায়; আগের উদ্বেগের বিপরীতে ভালো খবর।":"यह वाक्य कहानी का मोड़ बदलता है; पिछली चिंता के विपरीत अच्छी खबर।","সমাধান হিসেবে আলোচনা এসেছে; কোনো দেশের সব মানুষকে নিয়ে নিয়ম বলা হয়নি।":"समाधान के रूप में चर्चा आई है; किसी देश के सभी लोगों को लेकर नियम नहीं कहा गया।","শেষ বাক্য ঘটনাটির সাধারণ শিক্ষা; উদাহরণের বাইরে অতিরিক্ত ফল দাবি করা হয়নি।":"अंतिम वाक्य घटना की सामान्य शिक्षा है; उदाहरण के बाहर अतिरिक्त परिणाम का दावा नहीं किया गया।","ক্লাসের অনুশীলনের জন্য ধরে নিই, ২০ শিক্ষার্থীকে যাতায়াতের উপায় জিজ্ঞেস করা হলো।":"कक्षा के अभ्यास के लिए मान लें, 20 विद्यार्थियों से आवागमन के साधन पूछे गए।","ম্যানেজার বললেন, “একই ব্যাখ্যা বারবার বলাই যথেষ্ট নয়।”":"मैनेजर ने कहा, \"एक ही व्याख्या बार-बार कहना ही पर्याप्त नहीं।\"","তার মনে হলো, যেন গুরুত্বপূর্ণ কথাগুলোও হারিয়ে গেছে।":"उसे लगा, जैसे महत्वपूर्ण बातें भी खो गई हैं।","しかし আগের প্রত্যাশার সঙ্গে বাস্তব অবস্থার অমিল আনে।":"しかし पिछली अपेक्षा से वास्तविक स्थिति का अमेल लाता है।","এই দৃশ্যে কী বোঝায় বলা হয়েছে; সব ক্ষেত্রে একই অর্থ দাবি করা হয়নি।":"इस दृश्य में क्या समझाता है कहा गया है; सभी मामलों में एक ही अर्थ का दावा नहीं किया गया।","খাতাটি হাতে পেয়ে ইউ না হেসে থাকতে পারল না।":"कॉपी हाथ में पाकर यू न हँसे रह नहीं सका।","পরদিন স্টেশন থেকে জানানো হলো খাতাটি পাওয়া গেছে।":"अगले दिन स्टेशन से बताया गया कॉपी मिल गई है।","দুজন সময়সূচি নিশ্চিত করার গুরুত্ব নিয়ে আলোচনা করল।":"दोनों ने समय-सारणी निश्चित करने के महत्व पर चर्चा की।","কিন্তু বন্ধু তখন কাজে বের হওয়ার ঠিক আগের অবস্থায় ছিল।":"लेकिन दोस्त तब काम पर निकलने से ठीक पहले की स्थिति में था।","তারপর বলল, “কাজ আছে, তবে রবিবার হলে সাহায্য করতে পারব।”":"फिर कहा, \"काम है, लेकिन रविवार होने पर सहायता कर सकूँगा।\"","এটি অনুশীলনের কাল্পনিক জরিপ; বাস্তব গবেষণা নয়।":"यह अभ्यास का काल्पनिक सर्वेक्षण है; वास्तविक शोध नहीं।","বন্ধু বলল, “আগামীকাল একটু কঠিন হবে।”":"दोस्त ने कहा, \"कल थोड़ा कठिन होगा।\"","প্রথম বাক্যে সমস্যাটি এসেছে; খাতাটির দৈনন্দিন গুরুত্বও জানা গেল।":"पहले वाक्य में समस्या आई है; कॉपी का दैनिक महत्व भी ज्ञात हुआ।","বাসায় পৌঁছানো মাত্র সে বিষয়টি টের পেল।":"घर पहुँचते ही वह विषय जान गया।","অনুরোধের বিষয় ও সময় আগে দেওয়া হয়েছে।":"अनुरोध का विषय और समय पहले दिया गया है।","পরদিন সে কোনো যোগাযোগ না করেই বন্ধুর বাসায় গেল।":"अगले दिन वह कोई संपर्क न करके ही दोस्त के घर गई।","しかし উপসংহারের সীমা নির্দেশ করে।":"しかし उपसंहार की सीमा निर्देश करता है।","মোট ১২+৫+৩=২০; গণনার ভিত্তি একই আছে।":"कुल 12+5+3=20; गणना का आधार एक ही है।","শেষ বাক্য লেখার মূল শিক্ষা।":"अंतिम वाक्य लेख की मूल शिक्षा है।","最初[さいしょ]は প্রথম প্রস্তাব চিহ্নিত করছে; এটি চূড়ান্ত সমাধান নয়।":"最初[さいしょ]は पहले प्रस्ताव को दर्शा रहा है; यह अंतिम समाधान नहीं है।","প্রথমে নির্দেশনার কাগজ বাড়ানোর কথা ভাবা হলো।":"पहले निर्देश का कागज़ बढ़ाने की बात सोची गई।","এই অভিজ্ঞতার মাধ্যমে মিনা কথার পাশাপাশি পরিস্থিতিও যাচাই করতে শুরু করল।":"इस अनुभव के माध्यम से मीना बात के साथ-साथ स्थिति भी जाँचने लगी।","কারণ লক্ষ্যগোষ্ঠী কেবল একটি ক্লাস।":"कारण लक्ष्य समूह केवल एक कक्षा है।","১২ জন ট্রেন, ৫ জন সাইকেল এবং ৩ জন হেঁটে যাওয়ার কথা বলল।":"12 लोगों ने ट्रेन, 5 ने साइकिल और 3 ने पैदल जाने की बात कही।","かのように উপমা; বাস্তবে সব কথা মুছে গেছে এমন তথ্য নয়।":"かのように उपमा; वास्तव में सभी बातें मिट गई हैं ऐसी जानकारी नहीं।","聞[き]きました-র প্রশ্নবিষয় দিয়ে পরের উত্তরের কেন্দ্র নির্ধারিত হয়।":"聞[き]きました के प्रश्न-विषय से अगले उत्तर का केंद्र निर्धारित होता है।","ট্রেন ব্যবহারকারীর অনুপাত ৬০ শতাংশ।":"ट्रेन उपयोगकर्ताओं का अनुपात 60 प्रतिशत।","তাই কর্মীরা পরিচিত ভাষায় লেখা নির্দেশনা ব্যবহার করলেন।":"इसलिए कर्मचारियों ने परिचित भाषा में लिखे निर्देश उपयोग किए।","এখানে 難[むずか]しい কেবল কাজের জটিলতা নাও বোঝাতে পারে।":"यहाँ 難[むずか]しい केवल काम की जटिलता को ही नहीं दर्शा सकता है।","を通[とお]して অভিজ্ঞতার মাধ্যমে শেখা; ようになった আচরণের পরিবর্তন।":"を通[とお]して अनुभव के माध्यम से सीखना; ようになった व्यवहार में परिवर्तन।","に応[おう]じて মানিয়ে নেওয়া; そうです বক্তার কাছ থেকে শোনা তথ্য।":"に応[おう]じて अनुकूल बनाना; そうです वक्ता से सुनी हुई जानकारी।","たとたん পৌঁছানোর সঙ্গে হঠাৎ উপলব্ধি বোঝায়।":"たとたん पहुँचने के साथ अचानक अनुभूति समझाता है।","গ্রাহকের চাহিদা অনুযায়ী তিনি ব্যাখ্যার ক্রম ও ভাষা বদলান।":"ग्राहक की माँग के अनुसार वह व्याख्या का क्रम और भाषा बदलता है।","ことなく মানে না করে; মিনার আগেই খবর না দেওয়া এখানে গুরুত্বপূর্ণ।":"ことなく का अर्थ न करके; मीना का पहले ही खबर न देना यहाँ महत्वपूर्ण है।","কেন এক বন্ধুকে পরদিন বাসা বদলে সাহায্য করতে বলল।":"केन ने एक दोस्त से अगले दिन घर बदलने में सहायता करने को कहा।","শেষ বাক্য প্রতিবেদকের উপলব্ধি; ম্যানেজারের সরাসরি উদ্ধৃতি নয়।":"अंतिम वाक्य रिपोर्टर की अनुभूति है; मैनेजर का सीधा उद्धरण नहीं।","মনে হলো, মন দিয়ে অন্যের কথা শোনাই আস্থার শুরু।":"लगा, ध्यान से दूसरों की बात सुनना ही आस्था की शुरुआत है।","শেষ প্রতিক্রিয়া থেকে স্বস্তি ও আনন্দ বোঝা যায়।":"अंतिम प्रतिक्रिया से राहत और आनंद समझा जाता है।","প্রথম বাক্যে বলা তথ্যটি আমন্ত্রণের ভাষা; এখনো সময় নির্দিষ্ট হয়নি।":"पहले वाक्य में कही जानकारी निमंत्रण की भाषा है; अभी समय निर्दिष्ट नहीं हुआ।","কিন্তু ব্যবহারকারীদের সঙ্গে কথা বলে জানা গেল, শ্রেণিবিভাগের নাম বোঝা কঠিন।":"लेकिन उपयोगकर्ताओं से बात करके ज्ञात हुआ, वर्गीकरण के नाम समझना कठिन है।","ইউ প্রতিদিন ব্যবহার করা খাতাটি ট্রেনে ফেলে এল।":"यू हर दिन उपयोग की कॉपी ट्रेन में छोड़ आया।","だけでは十分[じゅうぶん]ではない সীমা দেখাচ্ছে; কোনো ব্যাখ্যাই প্রয়োজন নেই বলা হয়নি।":"だけでは十分[じゅうぶん]ではない सीमा दिखा रहा है; यह नहीं कहा गया कि किसी व्याख्या की आवश्यकता ही नहीं है।","এই পরিস্থিতিতে “কঠিন” কথাটি পরদিনের অনুরোধ প্রত্যাখ্যান করছে।":"इस स्थिति में \"कठिन\" बात अगले दिन के अनुरोध को अस्वीकार कर रही है।","অর্থ বুঝতে শব্দের পাশাপাশি প্রসঙ্গও জরুরি।":"अर्थ समझने के लिए शब्द के साथ-साथ प्रसंग भी ज़रूरी है।","そこで আগের তথ্যের ভিত্তিতে করা পদক্ষেপকে যুক্ত করছে।":"そこで पिछली जानकारी के आधार पर किए गए कदम को जोड़ रहा है।","মিনাকে এক বন্ধু বলল, “আবার বেড়াতে এসো।”":"मीना से एक दोस्त ने कहा, \"फिर घूमने आना।\"","にすぎない পরিসরের সীমাবদ্ধতা দেখায়।":"にすぎない दायरे की सीमाबद्धता दिखाता है।","একটি লাইব্রেরিতে বই খুঁজতে বেশি সময় লাগে বলে মতামত এসেছিল।":"एक पुस्तकालय में किताब खोजने में अधिक समय लगता है कहकर राय आई थी।","শুরুতে ব্যবহারকারীর সমস্যা তুলে ধরা হয়েছে।":"शुरुआत में उपयोगकर्ता की समस्या उजागर की गई है।","১২÷২০×১০০=৬০; শুধু সংখ্যা নয়, মোটের ভিত্তি দেখুন।":"12÷20×100=60; सिर्फ़ संख्या नहीं, कुल का आधार देखें।","তবে শুধু এই ফল দিয়ে জাপানের সব শিক্ষার্থী সম্পর্কে বলা যায় না।":"लेकिन सिर्फ़ इस परिणाम से जापान के सभी विद्यार्थियों के बारे में नहीं कहा जा सकता।","যেমন, প্রথমবার আসা ব্যক্তিকে ব্যবহারের পদ্ধতি দিয়ে বোঝানো শুরু করেন।":"जैसे, पहली बार आए व्यक्ति को उपयोग की विधि से समझाना शुरू करता है।"},"study.reading_title":{"“একটু কঠিন” কথাটির পর কী হলো":"“थोड़ा कठिन” कहने के बाद क्या हुआ","সমস্যার বদলে প্রয়োজন থেকে ভাবা":"समस्या के बजाय आवश्यकता से सोचना","ভালো সেবা মানে একই উত্তর নয়":"अच्छी सेवा का अर्थ एक ही उत्तर नहीं है","একটি আমন্ত্রণ, দুই রকম ধারণা":"एक निमंत्रण, दो तरह की धारणाएँ","হারানো খাতার ছোট গল্প":"खोई हुई कॉपी की छोटी कहानी","জরিপের সংখ্যা থেকে কতটুকু বলা যায়":"सर्वेक्षण की संख्याओं से कितना कहा जा सकता है"},"study.strategy":{"শব্দের আক্ষরিক অর্থের পাশাপাশি কে, কাকে, কোন অনুরোধে বলছে তা দেখুন। পরোক্ষ কথাকে সবার জন্য স্থির নিয়ম হিসেবে ধরবেন না।":"शब्द के शाब्दिक अर्थ के साथ-साथ कौन, किससे, किस अनुरोध में कह रहा है यह देखें। अप्रत्यक्ष बात को सभी के लिए स्थिर नियम के रूप में न पकड़ें।","শিরোনাম ও ছোট উপশিরোনাম দেখে যুক্তির ধাপ ধরুন। দাবি, কারণ, উদাহরণ ও বিকল্পকে আলাদা করুন। মতের বিরোধিতা করলে কারণসহ বিকল্প দিন।":"शीर्षक और छोटे उपशीर्षक देखकर तर्क के चरण पकड़ें। दावा, कारण, उदाहरण और विकल्प को अलग करें। राय का विरोध करने पर कारण सहित विकल्प दें।","চরিত্রের অনুভূতি কোন ঘটনা বা শব্দে বদলেছে তা দেখুন। উপমাকে বাস্তব ঘটনা হিসেবে নেবেন না। পর্যালোচনায় নিজের মূল্যায়নের কারণ দিন।":"पात्र की भावना किस घटना या शब्द से बदली है यह देखें। उपमा को वास्तविक घटना के रूप में न लें। समीक्षा में अपने मूल्यांकन का कारण दें।","প্রশ্নের উত্তরে বক্তা প্রথমে সিদ্ধান্ত বলেছেন, না উদাহরণ দিয়েছেন, তা ধরুন। উদাহরণ কোন মূল কথাকে বোঝাচ্ছে সেটি খুঁজুন।":"प्रश्न के उत्तर में वक्ता ने पहले निर्णय कहा है या उदाहरण दिया है, यह पकड़ें। उदाहरण किस मूल बात को समझा रहा है यह खोजें।","বাক্যে কর্তা বাদ গেলে আগের বাক্য ও কথোপকথনের প্রবাহ দেখুন। অনুমান আর স্পষ্টভাবে বলা তথ্য আলাদা রাখুন।":"वाक्य में कर्ता छूटने पर पिछला वाक्य और बातचीत का प्रवाह देखें। अनुमान और स्पष्ट रूप से कही जानकारी अलग रखें।","জরিপের লক্ষ্যগোষ্ঠী, মোট উত্তরদাতা, সময় ও শতাংশের ভিত্তি আগে পড়ুন। উদাহরণের সংখ্যাকে বাস্তব জরিপের ফল হিসেবে ব্যবহার করবেন না।":"सर्वेक्षण का लक्ष्य समूह, कुल उत्तरदाता, समय और प्रतिशत का आधार पहले पढ़ें। उदाहरण की संख्याओं को वास्तविक सर्वेक्षण के परिणाम के रूप में उपयोग न करें।"},"study.vocab":{"প্রকাশভঙ্গি":"अभिव्यक्ति शैली","দৃষ্টিকোণ":"दृष्टिकोण","ভুল বোঝাবুঝি":"ग़लतफ़हमी","অনুভূতি":"भावना","আস্থা":"आस्था","উদ্বেগ":"चिंता","অভিজ্ঞতা":"अनुभव","লক্ষ্যগোষ্ঠী বা বিষয়":"लक्ष्य समूह या विषय","জরিপ বা অনুসন্ধান":"सर्वेक्षण या अनुसंधान","অনুপাত":"अनुपात","উদ্দেশ্য":"उद्देश्य","অন্যের কথা বিবেচনা":"दूसरों की बात का विचार","প্রসঙ্গ":"प्रसंग","ভূমিকা":"भूमिका","সংকোচ বা সংযম":"संकोच या संयम","চিন্তার সূচনা বা ধারণা":"सोच की शुरुआत या धारणा","পারস্পরিক আদানপ্রদান":"पारस्परिक आदान-प्रदान","কৌশল বা বুদ্ধিদীপ্ত চেষ্টা":"कौशल या बुद्धिमान कोशिश","সহযোগিতা":"सहयोग","চাহিদা বা আশা":"माँग या आशा","ভিন্ন সংস্কৃতি":"भिन्न संस्कृति","প্রস্তাব":"प्रस्ताव","অভ্যাস বা রীতি":"आदत या रीति","স্বস্তি":"राहत","গ্রাহকসেবা":"ग्राहक सेवा","হ্রাস":"कमी","মনের ওপর ছাপ":"मन पर छाप","বৃদ্ধি":"वृद्धि","তুলনা":"तुलना","গল্প বা আখ্যান":"कहानी या आख्यान","দৃশ্য বা পরিস্থিতি":"दृश्य या परिस्थिति","যাচাই করা":"जाँचना","প্রত্যাখ্যান করা":"अस्वीकार करना","উন্নতি":"उन्नति","জানানো":"बताना"},"study.writing":{"আমি খাতা হারানো একজনের ছোট গল্প পড়েছি।":"मैंने कॉपी खोए एक व्यक्ति की छोटी कहानी पढ़ी है।","ট্রেন ব্যবহারকারী ১২ জন, যা সবচেয়ে বড় অংশ।":"ट्रेन उपयोगकर्ता 12 लोग, जो सबसे बड़ा भाग है।","কিন্তু বন্ধু ভেবেছিল এখনো আলোচনা দরকার।":"लेकिन दोस्त ने सोचा था अभी चर्चा ज़रूरी है।","আমারও প্রিয় জিনিস হারানোর অভিজ্ঞতা আছে বলে অনুভূতিটি বুঝেছি।":"मुझे भी प्रिय चीज़ खोने का अनुभव है कहकर भावना समझी है।","অনুশীলনের জরিপে একটি ক্লাসের ২০ শিক্ষার্থীকে প্রশ্ন করা হয়েছে।":"अभ्यास के सर्वेक्षण में एक कक्षा के 20 विद्यार्थियों से प्रश्न किया गया है।","এই অভিজ্ঞতার পর গুরুত্বপূর্ণ বিষয় স্পষ্টভাবে বলে নিশ্চিত করার চেষ্টা করি।":"इस अनुभव के बाद महत्वपूर्ण विषय स्पष्ट रूप से कहकर निश्चित करने की कोशिश करता हूँ।","মূল চরিত্রের উদ্বেগ পরিচিত ভাষায় তুলে ধরা হয়েছে।":"मुख्य पात्र की चिंता परिचित भाषा में उजागर की गई है।","যেমন কঠিন শব্দ পরিচিত প্রকাশে বদলে দেওয়া যায়।":"जैसे कठिन शब्द परिचित प्रयोग में बदले जा सकते हैं।","তাই যারা ব্যবহার করবেন তাঁদের মতামত শোনা উচিত বলে মনে করি।":"इसलिए जो उपयोग करेंगे उनकी राय सुननी चाहिए ऐसा मानता हूँ।","এটি এমন গল্প যা দৈনন্দিন ছোট ঘটনাকেও গুরুত্ব দিতে শেখায়।":"यह ऐसी कहानी है जो दैनिक छोटी घटना को भी महत्व देना सिखाती है।","আমি ভেবেছিলাম সময় ঠিক হয়ে গেছে।":"मैंने सोचा था समय तय हो गया है।","সম্পর্ক ও পরিস্থিতি অনুযায়ী তা বদলায়।":"संबंध और स्थिति के अनुसार वह बदलता है।","আমার মতে নির্দেশনা তৈরির সময় ব্যবহারকারীর দৃষ্টিকোণ জরুরি।":"मेरे अनुसार निर्देश बनाते समय उपयोगकर्ता का दृष्टिकोण ज़रूरी है।","দীর্ঘ অভিজ্ঞতার ভিত্তিতে তিনি বোঝানোর ধরনে কৌশল ব্যবহার করেন।":"लंबे अनुभव के आधार पर वह समझाने के ढंग में कौशल उपयोग करता है।","তাঁর মতে সবচেয়ে গুরুত্বপূর্ণ হলো গ্রাহকের কথা শোনা।":"उसके अनुसार सबसे महत्वपूर्ण है ग्राहक की बात सुनना।","আমি পাশের দোকানের ম্যানেজারের সাক্ষাৎকার নিয়েছি।":"मैंने पास की दुकान के मैनेजर का साक्षात्कार लिया है।","জাপানিতে কোনো সময় না করার আগে কারণ বলা হয়।":"जापानी में किसी समय न करने से पहले कारण कहा जाता है।","না বুঝলে আমি ভদ্রভাবে নিশ্চিত হতে চাই।":"न समझने पर मैं विनम्रता से निश्चित होना चाहता हूँ।","আমিও অন্যের অবস্থান বিবেচনা করে কাজ করতে চাই বলে মনে হয়েছে।":"मुझे भी दूसरों की स्थिति विचार करके काम करना चाहता हूँ ऐसा लगा है।","তবে সবসময় একই প্রকাশ ব্যবহার হয় না।":"लेकिन हमेशा एक ही प्रयोग उपयोग नहीं होता।","জাপানে নতুন আসার সময় এক বন্ধুর সঙ্গে কথা দেওয়া নিয়ে সমস্যায় পড়েছিলাম।":"जापान में नया आने के समय एक दोस्त के साथ वादा करने को लेकर समस्या में पड़ा था।","সাইকেল ব্যবহারকারীর তুলনায় ৭ জন বেশি।":"साइकिल उपयोगकर्ताओं की तुलना में 7 लोग अधिक।","কারণ তথ্য বেশি হলেই অর্থ পরিষ্কার হয় এমন নয়।":"कारण जानकारी अधिक होने से ही अर्थ स्पष्ट होता है ऐसा नहीं।","তবে অল্পসংখ্যক ব্যক্তির ফল বলে এটি সামগ্রিক প্রবণতা নাও হতে পারে।":"लेकिन अल्पसंख्यक लोगों का परिणाम होने से यह समग्र प्रवृत्ति न भी हो सकती है।"},"study.writing_prompt":{"নিজের একটি ভুল বোঝাবুঝির অভিজ্ঞতা লিখুন: ঘটনা → নিজের ধারণা → অন্য পক্ষের অবস্থা → পরেরবার কী করবেন।":"अपना एक ग़लतफ़हमी का अनुभव लिखें: घटना → अपनी धारणा → दूसरे पक्ष की स्थिति → अगली बार क्या करेंगे।","বাংলা ও জাপানিতে কোনো অনুরোধ ফিরিয়ে দেওয়ার একটি করে উদাহরণ দিন। শব্দের অর্থ, সম্পর্ক ও পরিস্থিতি আলাদা করে লিখুন; জাতিগত সাধারণীকরণ এড়িয়ে চলুন।":"हिंदी और जापानी में किसी अनुरोध को लौटाने का एक-एक उदाहरण दें। शब्द का अर्थ, संबंध और स्थिति अलग करके लिखें; जातिगत सामान्यीकरण से बचें।","একটি গল্প বা সিনেমার সংক্ষিপ্ত রিভিউ লিখুন: পরিচয় → একটি দৃশ্য → নিজের অনুভূতি → সুপারিশের কারণ। সমাপ্তির সব তথ্য বলে দেবেন না।":"एक कहानी या फ़िल्म की संक्षिप्त समीक्षा लिखें: परिचय → एक दृश्य → अपनी भावना → सिफ़ारिश का कारण। समापन की सभी जानकारी न बता दें।","এই কাল্পনিক সংখ্যাগুলো ব্যবহার করে চার বাক্যের প্রতিবেদন লিখুন। লক্ষ্যগোষ্ঠী → সবচেয়ে বড় অংশ → তুলনা → সিদ্ধান্তের সীমা।":"इन काल्पनिक संख्याओं का उपयोग करके चार वाक्यों की रिपोर्ट लिखें। लक्ष्य समूह → सबसे बड़ा भाग → तुलना → निर्णय की सीमा।","একটি ছোট সমস্যা বেছে ১৮০–২৫০ জাপানি অক্ষরে মতামত লিখুন: দাবি → কারণ → উদাহরণ → সম্ভাব্য আপত্তি → বাস্তব প্রস্তাব।":"एक छोटी समस्या चुनकर 180–250 जापानी अक्षरों में राय लिखें: दावा → कारण → उदाहरण → संभाव्य आपत्ति → वास्तविक प्रस्ताव।","কোনো পরিচিত ব্যক্তির কাজ সম্পর্কে তিনটি প্রশ্ন করুন। সরাসরি উক্তি এবং নিজের উপলব্ধি আলাদা করে একটি ছোট প্রতিবেদন লিখুন।":"किसी परिचित व्यक्ति के काम के बारे में तीन प्रश्न करें। सीधा कथन और अपनी अनुभूति अलग करके एक छोटी रिपोर्ट लिखें।"},"title":{"QUARTET II · বাংলা গ্রামার সহায়িকা":"QUARTET II · हिंदी व्याकरण सहायक"}},"qa":{"attr.aside@aria-label":{"পাঠ নির্বাচন":"पाठ का चयन"},"attr.div@aria-label":{"পড়ার ধরন":"पढ़ने का तरीका"},"attr.input@aria-label":{"গ্রামার খুঁজুন":"व्याकरण खोजें"},"attr.meta@description":{"QUARTET Ⅱ-এর অধ্যায় ৭–১২-এর থিমে নির্বাচিত ৩৬টি বিষয়ে নিজস্ব বাংলা ব্যাখ্যা, ফুরিগানাসহ উদাহরণ ও অনুশীলন।":"QUARTET Ⅱ के अध्याय 7–12 की थीम पर चुने गए 36 विषयों पर अपनी हिंदी व्याख्या, फुरिगाना सहित उदाहरण और अभ्यास।"},"attr.nav@aria-label":{"এই অধ্যায়ের গ্রামার":"इस अध्याय का व्याकरण","QUARTET বই ও পড়ার ধরন":"QUARTET किताब और पढ़ने की शैली","পথ নির্দেশনা":"मार्गदर्शन"},"attr.progress@aria-label":{"গ্রামার শেখার অগ্রগতি":"व्याकरण सीखने की प्रगति"},"text.uncovered":{"পাঠ ও অনুশীলন খুলতে JavaScript চালু করুন।":"पाठ और अभ्यास खोलने के लिए JavaScript चालू करें।","N2 Grammar পড়ুন":"N2 Grammar पढ़ें"}}};
